// AgilePM v3 Foundation — extended "Zen mode" question bank.
//
// A large set of exam-style multiple-choice questions sourced from the AgilePM
// v3 reference book, the AgilePM Foundation syllabus and sample/mock papers.
// Each question: { id, topic, q, options[], correct (matches one option), explain }.
// `correct` MUST be one of the strings in `options`. Option order here is
// irrelevant — the Zen runner re-shuffles options at runtime.
//
// Topic codes match TOPICS in agileContent.js:
//   KC Key Concepts · SC Scrum Overview · AF AgilePM Fundamentals
//   IN Individuals & Interactions · CC Collaboration & Communication
//   PR Project Lifecycle Framework · ES Requirements, Estimating & Prioritisation
//   PC Planning & Control · RK Risk Management & the Project Approach
//   GV Governance, Compliance & Products

export const ZEN_QUESTIONS = [
  // ===================================================================
  // KC — Key Concepts
  // ===================================================================
  { id: 'z-kc-1', topic: 'KC', q: 'Which body is the professional body for business agility worldwide (formerly the DSDM Consortium)?', options: ['The Agile Business Consortium', 'The Scrum Alliance', 'APMG International', 'The Project Management Institute'], correct: 'The Agile Business Consortium', explain: 'The DSDM Consortium rebranded to the Agile Business Consortium in 2016.' },
  { id: 'z-kc-2', topic: 'KC', q: 'In what year was the DSDM Consortium formed?', options: ['1994', '2001', '2010', '1991'], correct: '1994', explain: 'The DSDM Consortium was formed in 1994 to define an industry standard for delivery.' },
  { id: 'z-kc-3', topic: 'KC', q: 'When was AgilePM first released?', options: ['2010', '2001', '1994', '2014'], correct: '2010', explain: 'AgilePM was first released in 2010 by the DSDM Consortium.' },
  { id: 'z-kc-4', topic: 'KC', q: 'Which framework did the Agile Business Consortium develop, into which AgilePM fits in the "change" segment?', options: ['The Framework for Business Agility (FBA)', 'SAFe', 'The Scrum Guide', 'PRINCE2 Agile'], correct: 'The Framework for Business Agility (FBA)', explain: 'AgilePM addresses the "change" segment of the FBA.' },
  { id: 'z-kc-5', topic: 'KC', q: 'How is Business Agility defined by the Agile Business Consortium?', options: ['A progressive, people-centric approach to all aspects of business', 'A software development methodology', 'A documentation and audit framework', 'A contract negotiation technique'], correct: 'A progressive, people-centric approach to all aspects of business', explain: 'It transforms how organisations operate and succeed in the modern world.' },
  { id: 'z-kc-6', topic: 'KC', q: 'What does VUCA stand for?', options: ['Volatility, Uncertainty, Complexity, Ambiguity', 'Value, Uncertainty, Capability, Agility', 'Volatility, Understanding, Complexity, Adaptability', 'Vision, Uncertainty, Collaboration, Ambiguity'], correct: 'Volatility, Uncertainty, Complexity, Ambiguity', explain: 'VUCA describes the modern operating environment AgilePM is designed to cope with.' },
  { id: 'z-kc-7', topic: 'KC', q: 'In VUCA, which element means "information or situations can have more than one possible meaning"?', options: ['Ambiguity', 'Uncertainty', 'Complexity', 'Volatility'], correct: 'Ambiguity', explain: 'Ambiguity = multiple possible interpretations of information.' },
  { id: 'z-kc-8', topic: 'KC', q: 'In VUCA, "many interconnected parts where cause and effect is unclear" describes which element?', options: ['Complexity', 'Volatility', 'Ambiguity', 'Uncertainty'], correct: 'Complexity', explain: 'Complexity = many interconnected parts, unclear cause/effect.' },
  { id: 'z-kc-9', topic: 'KC', q: 'When and where was the Agile Manifesto created?', options: ['February 2001, Snowbird, Utah', '1994, London', '2010, Boston', '2001, Silicon Valley'], correct: 'February 2001, Snowbird, Utah', explain: 'It was created in February 2001 by 17 experts in Snowbird, Utah.' },
  { id: 'z-kc-10', topic: 'KC', q: 'How many experts created the original Agile Manifesto?', options: ['17', '12', '4', '8'], correct: '17', explain: '17 software development experts met at Snowbird.' },
  { id: 'z-kc-11', topic: 'KC', q: 'What single word did the Agile Business Consortium change in the Manifesto values?', options: ['"Software" became "solutions"', '"Customer" became "stakeholder"', '"Plan" became "roadmap"', '"Documentation" became "records"'], correct: '"Software" became "solutions"', explain: 'This broadens value creation beyond software development.' },
  { id: 'z-kc-12', topic: 'KC', q: 'Which is the first value of the Agile Manifesto?', options: ['Individuals and interactions over processes and tools', 'Working solutions over comprehensive documentation', 'Customer collaboration over contract negotiation', 'Responding to change over following a plan'], correct: 'Individuals and interactions over processes and tools', explain: 'It is the first of the four Manifesto values.' },
  { id: 'z-kc-13', topic: 'KC', q: 'What does the Manifesto\'s closing sentence emphasise?', options: ['The right-hand items still have value, but the left are valued more', 'The right-hand items should be discarded', 'Only the left-hand items have any value', 'Documentation has no value at all'], correct: 'The right-hand items still have value, but the left are valued more', explain: '"While there is value in the items on the right, we value the items on the left more."' },
  { id: 'z-kc-14', topic: 'KC', q: 'Empowerment requires people to be which three things?', options: ['Capable, Willing and Informed', 'Skilled, Senior and Available', 'Trained, Trusted and Tested', 'Motivated, Managed and Monitored'], correct: 'Capable, Willing and Informed', explain: 'Capable (skills), Willing (ready to take responsibility), Informed (enough data).' },
  { id: 'z-kc-15', topic: 'KC', q: 'What is the "last responsible moment"?', options: ['The point when information is actually needed to take the next step', 'The project deadline', 'The end of the Foundations Phase', 'The moment a Sprint is cancelled'], correct: 'The point when information is actually needed to take the next step', explain: 'Detailed work is deferred to this point so it stays relevant.' },
  { id: 'z-kc-16', topic: 'KC', q: 'Why is the last responsible moment more efficient?', options: ['Near-future predictions are more reliable and less effort is wasted', 'It removes the need for any estimates', 'It guarantees a fixed scope', 'It avoids any customer involvement'], correct: 'Near-future predictions are more reliable and less effort is wasted', explain: 'Later decisions benefit from learning and tested assumptions.' },
  { id: 'z-kc-17', topic: 'KC', q: 'What advantage does an iterative approach bring?', options: ['It tests and questions assumptions early, reducing uncertainty', 'It delivers everything only at the very end', 'It removes the need for feedback', 'It fixes the features up front'], correct: 'It tests and questions assumptions early, reducing uncertainty', explain: 'Iteration lets the right solution emerge through feedback.' },
  { id: 'z-kc-18', topic: 'KC', q: 'What advantage does an incremental approach to delivery bring?', options: ['The organisation gains value early and the business case strengthens', 'It delays all value until project end', 'It avoids deploying anything', 'It prevents users engaging with the product'], correct: 'The organisation gains value early and the business case strengthens', explain: 'Benefits are seen and measured as parts go live.' },
  { id: 'z-kc-19', topic: 'KC', q: 'What is the primary measure of progress in agile?', options: ['Working solutions', 'Percentage of tasks complete', 'Pages of documentation produced', 'Hours logged'], correct: 'Working solutions', explain: 'Manifesto principle 7: working solutions are the primary measure of progress.' },
  { id: 'z-kc-20', topic: 'KC', q: 'What is "Taylorism" (Scientific Management) associated with?', options: ['Efficiency, automation and strict procedure-following', 'Self-organising empowered teams', 'Iterative customer collaboration', 'Light-touch documentation'], correct: 'Efficiency, automation and strict procedure-following', explain: 'It treated workers as operators following rigid procedures.' },
  { id: 'z-kc-21', topic: 'KC', q: 'What are the two contexts in which product development happens (per AgilePM)?', options: ['Project Management and Product Lifecycle Management', 'Design and Build', 'Sales and Operations', 'Testing and Deployment'], correct: 'Project Management and Product Lifecycle Management', explain: 'AgilePM situates development within PM and PLM contexts.' },
  { id: 'z-kc-22', topic: 'KC', q: 'What is "latent value"?', options: ['Potential value realised only when the product is actually used', 'Value lost through delay', 'Value written in the business case', 'Value of unfinished work'], correct: 'Potential value realised only when the product is actually used', explain: 'A solution-focused view ensures latent value is captured.' },
  { id: 'z-kc-23', topic: 'KC', q: 'What flawed assumption underpins legacy/waterfall methods?', options: ['That the problem and design will not change much during the project', 'That requirements will constantly change', 'That the customer is always available', 'That documentation is unnecessary'], correct: 'That the problem and design will not change much during the project', explain: 'This fails in a VUCA environment where change is constant.' },
  { id: 'z-kc-24', topic: 'KC', q: 'When is Scrum LEAST suited?', options: ['For standardised, highly repetitive routine work', 'For complex R&D and product development', 'Where the solution is not fully known', 'Where collaboration works best'], correct: 'For standardised, highly repetitive routine work', explain: 'Routine, well-defined work (e.g. manufacturing) does not benefit from Scrum.' },
  { id: 'z-kc-25', topic: 'KC', q: 'What is Product Lifecycle Management (PLM) concerned with?', options: ['The product across its entire life: ideation, distribution, servicing, retirement', 'Only the build phase', 'Only marketing', 'Only the project budget'], correct: 'The product across its entire life: ideation, distribution, servicing, retirement', explain: 'PLM takes the long-term whole-of-life view.' },
  { id: 'z-kc-26', topic: 'KC', q: 'What characteristics should agile documents have?', options: ['Light-touch, guiding, visible and clearly understood', 'Highly detailed and controlling', 'Rigid and restrictive', 'Hidden from most stakeholders'], correct: 'Light-touch, guiding, visible and clearly understood', explain: 'Agile documents guide rather than control.' },
  { id: 'z-kc-27', topic: 'KC', q: 'How does AgilePM define a "customer"?', options: ['Anyone who will benefit from, use or be affected by the project\'s work', 'Only the person who signs the contract', 'Only end users of software', 'Only the Business Sponsor'], correct: 'Anyone who will benefit from, use or be affected by the project\'s work', explain: 'It is a broad definition including buyers, users and those affected.' },
  { id: 'z-kc-28', topic: 'KC', q: 'Why are traditional fixed-scope contracts problematic for agile projects?', options: ['They assume nothing will change', 'They are too short to read', 'They cost too much to print', 'They are always illegal'], correct: 'They assume nothing will change', explain: 'Agile contracts must allow flexibility as requirements evolve.' },
  { id: 'z-kc-29', topic: 'KC', q: 'What did Rapid Application Development (RAD) struggle with?', options: ['Quality, because teams moved straight into development without enough analysis/design', 'Too much documentation', 'Too little customer involvement', 'Excessive up-front specification'], correct: 'Quality, because teams moved straight into development without enough analysis/design', explain: 'RAD\'s focus on speed/quick fixes hurt quality.' },
  { id: 'z-kc-30', topic: 'KC', q: 'How did DSDM combine Waterfall and RAD?', options: ['It took control/quality from Waterfall and iteration/business involvement from RAD', 'It rejected both entirely', 'It used only Waterfall', 'It used only RAD'], correct: 'It took control/quality from Waterfall and iteration/business involvement from RAD', explain: 'DSDM blended the best of both.' },
  { id: 'z-kc-31', topic: 'KC', q: 'Which best describes Product Development?', options: ['Taking a product from initial idea to where it meets the needs of its users', 'Overseeing the project environment', 'Producing the Business Case', 'Auditing regulatory compliance'], correct: 'Taking a product from initial idea to where it meets the needs of its users', explain: 'It focuses on what the product is and how it is built and improved.' },
  { id: 'z-kc-32', topic: 'KC', q: 'Why is product management agility valuable even on a "stable" project?', options: ['It still improves communication, involvement and incremental benefit delivery', 'It guarantees zero change', 'It removes the need for a Business Case', 'It replaces governance'], correct: 'It still improves communication, involvement and incremental benefit delivery', explain: 'Agility adds value even when change is low.' },

  // ===================================================================
  // SC — Scrum Overview
  // ===================================================================
  { id: 'z-sc-1', topic: 'SC', q: 'How does the Scrum Guide define Scrum?', options: ['A lightweight framework that helps generate value through adaptive solutions for complex problems', 'A detailed methodology with fixed documentation', 'A contract-management technique', 'A portfolio governance model'], correct: 'A lightweight framework that helps generate value through adaptive solutions for complex problems', explain: 'This is the 2020 Scrum Guide definition.' },
  { id: 'z-sc-2', topic: 'SC', q: 'Scrum is founded on which two things?', options: ['Empiricism and lean thinking', 'Waterfall and Six Sigma', 'Documentation and governance', 'Contracts and compliance'], correct: 'Empiricism and lean thinking', explain: 'Empiricism (knowledge from experience) and lean thinking (reduce waste).' },
  { id: 'z-sc-3', topic: 'SC', q: 'What are the three pillars of empiricism?', options: ['Transparency, Inspection, Adaptation', 'Plan, Do, Check', 'Commitment, Focus, Courage', 'Time, Cost, Quality'], correct: 'Transparency, Inspection, Adaptation', explain: 'These three pillars uphold every empirical process.' },
  { id: 'z-sc-4', topic: 'SC', q: 'Transparency enables which pillar?', options: ['Inspection', 'Adaptation', 'Estimation', 'Governance'], correct: 'Inspection', explain: 'Transparency without inspection is misleading and wasteful.' },
  { id: 'z-sc-5', topic: 'SC', q: 'Inspection enables which pillar?', options: ['Adaptation', 'Transparency', 'Documentation', 'Negotiation'], correct: 'Adaptation', explain: 'Inspection without adaptation is pointless.' },
  { id: 'z-sc-6', topic: 'SC', q: 'What are the five Scrum Values?', options: ['Commitment, Focus, Openness, Respect, Courage', 'Trust, Honesty, Speed, Quality, Value', 'Transparency, Inspection, Adaptation, Lean, Agile', 'Plan, Build, Test, Review, Deploy'], correct: 'Commitment, Focus, Openness, Respect, Courage', explain: 'The five Scrum Values.' },
  { id: 'z-sc-7', topic: 'SC', q: 'What is the maximum recommended Scrum Team size?', options: ['10 or fewer people', '7 people', '15 people', '20 people'], correct: '10 or fewer people', explain: 'Small enough to stay nimble, large enough to do significant work.' },
  { id: 'z-sc-8', topic: 'SC', q: 'Who is accountable for maximising the value of the product?', options: ['The Product Owner', 'The Scrum Master', 'The Developers', 'The Project Manager'], correct: 'The Product Owner', explain: 'The PO maximises value and manages the Product Backlog.' },
  { id: 'z-sc-9', topic: 'SC', q: 'Why is the Product Owner one person, not a committee?', options: ['So the organisation respects a single decision-maker representing many stakeholders', 'Because committees are illegal', 'To reduce team size', 'To avoid paying more people'], correct: 'So the organisation respects a single decision-maker representing many stakeholders', explain: 'A single accountable PO keeps the backlog decisive.' },
  { id: 'z-sc-10', topic: 'SC', q: 'The Scrum Master is accountable for which two things?', options: ['Establishing Scrum and the Scrum Team\'s effectiveness', 'Writing the Business Case and budget', 'Owning the Product Backlog and value', 'Approving regulatory compliance'], correct: 'Establishing Scrum and the Scrum Team\'s effectiveness', explain: 'The SM is a true/servant leader for the team and organisation.' },
  { id: 'z-sc-11', topic: 'SC', q: 'What are the Developers accountable for?', options: ['Creating the Sprint plan, instilling quality via the DoD, and adapting daily', 'Owning the Business Case', 'Setting the project budget', 'Approving the Business Vision'], correct: 'Creating the Sprint plan, instilling quality via the DoD, and adapting daily', explain: 'Developers own the Sprint Backlog and how the work is done.' },
  { id: 'z-sc-12', topic: 'SC', q: 'What is the maximum length of a Sprint?', options: ['One month or less', 'Two weeks exactly', 'Six weeks', 'Three months'], correct: 'One month or less', explain: 'Sprints are fixed-length events of one month or less.' },
  { id: 'z-sc-13', topic: 'SC', q: 'When does a new Sprint start?', options: ['Immediately after the conclusion of the previous Sprint', 'After a one-week break', 'Only when the Product Owner signs off', 'After deployment is complete'], correct: 'Immediately after the conclusion of the previous Sprint', explain: 'The Sprint is the heartbeat of Scrum with no gaps.' },
  { id: 'z-sc-14', topic: 'SC', q: 'Who can cancel a Sprint, and when?', options: ['Only the Product Owner, if the Sprint Goal becomes obsolete', 'The Scrum Master, at any time', 'Any Developer, when behind schedule', 'The Business Sponsor, on cost grounds'], correct: 'Only the Product Owner, if the Sprint Goal becomes obsolete', explain: 'Only the PO can cancel a Sprint.' },
  { id: 'z-sc-15', topic: 'SC', q: 'What is the maximum timebox for Sprint Planning (one-month Sprint)?', options: ['8 hours', '4 hours', '3 hours', '15 minutes'], correct: '8 hours', explain: 'Sprint Planning is timeboxed to a max of 8 hours.' },
  { id: 'z-sc-16', topic: 'SC', q: 'What three topics does Sprint Planning address, in order?', options: ['Why, What, How', 'What, Why, How', 'How, What, Why', 'Why, How, What'], correct: 'Why, What, How', explain: 'Why (Sprint Goal) → What (PBIs) → How (the plan).' },
  { id: 'z-sc-17', topic: 'SC', q: 'What is the Daily Scrum timebox?', options: ['15 minutes', '30 minutes', '1 hour', '4 hours'], correct: '15 minutes', explain: 'A 15-minute event for the Developers, same time and place daily.' },
  { id: 'z-sc-18', topic: 'SC', q: 'What is the purpose of the Daily Scrum?', options: ['Inspect progress toward the Sprint Goal and adapt the Sprint Backlog', 'Report status to management', 'Sign off completed work', 'Plan the next Sprint'], correct: 'Inspect progress toward the Sprint Goal and adapt the Sprint Backlog', explain: 'It is for the Developers to inspect and adapt.' },
  { id: 'z-sc-19', topic: 'SC', q: 'What is the Sprint Review timebox (one-month Sprint)?', options: ['Maximum 4 hours', 'Maximum 8 hours', 'Maximum 3 hours', '15 minutes'], correct: 'Maximum 4 hours', explain: 'Sprint Review is a max of 4 hours for a one-month Sprint.' },
  { id: 'z-sc-20', topic: 'SC', q: 'The Sprint Review should NOT be...', options: ['A presentation', 'A working session', 'An inspection of the outcome', 'A collaboration with stakeholders'], correct: 'A presentation', explain: 'It is a working session, not a presentation.' },
  { id: 'z-sc-21', topic: 'SC', q: 'What is the Sprint Retrospective timebox (one-month Sprint)?', options: ['Maximum 3 hours', 'Maximum 4 hours', 'Maximum 8 hours', '1 hour'], correct: 'Maximum 3 hours', explain: 'Retrospective is a max of 3 hours.' },
  { id: 'z-sc-22', topic: 'SC', q: 'What is the purpose of the Sprint Retrospective?', options: ['Plan ways to increase quality and effectiveness', 'Demonstrate the increment to stakeholders', 'Re-estimate the Product Backlog', 'Approve the Business Case'], correct: 'Plan ways to increase quality and effectiveness', explain: 'It inspects people, interactions, processes, tools and the DoD.' },
  { id: 'z-sc-23', topic: 'SC', q: 'What are the three Scrum Artifacts?', options: ['Product Backlog, Sprint Backlog, Increment', 'Vision, Roadmap, Plan', 'Business Case, SAD, DAD', 'Epic, Story, Task'], correct: 'Product Backlog, Sprint Backlog, Increment', explain: 'Each artifact has an attached commitment.' },
  { id: 'z-sc-24', topic: 'SC', q: 'Which commitment is attached to the Product Backlog?', options: ['The Product Goal', 'The Sprint Goal', 'The Definition of Done', 'The Business Case'], correct: 'The Product Goal', explain: 'Product Backlog → Product Goal.' },
  { id: 'z-sc-25', topic: 'SC', q: 'Which commitment is attached to the Sprint Backlog?', options: ['The Sprint Goal', 'The Product Goal', 'The Definition of Done', 'The Acceptance Criteria'], correct: 'The Sprint Goal', explain: 'Sprint Backlog → Sprint Goal.' },
  { id: 'z-sc-26', topic: 'SC', q: 'Which commitment is attached to the Increment?', options: ['The Definition of Done', 'The Sprint Goal', 'The Product Goal', 'The Business Case'], correct: 'The Definition of Done', explain: 'Increment → Definition of Done.' },
  { id: 'z-sc-27', topic: 'SC', q: 'What is the Product Backlog?', options: ['An emergent, ordered list of what is needed to improve the product', 'A fixed signed specification', 'A list of completed tasks', 'The Sprint plan'], correct: 'An emergent, ordered list of what is needed to improve the product', explain: 'It is the single source of work for the Scrum Team.' },
  { id: 'z-sc-28', topic: 'SC', q: 'What is Product Backlog refinement?', options: ['Breaking down and further defining items into smaller, more precise items', 'Approving the budget', 'Deploying the increment', 'Cancelling the Sprint'], correct: 'Breaking down and further defining items into smaller, more precise items', explain: 'An ongoing activity adding detail, order and size.' },
  { id: 'z-sc-29', topic: 'SC', q: 'What is the Sprint Goal?', options: ['The single objective for the Sprint', 'The future state of the product', 'The quality measures for the increment', 'The list of all backlog items'], correct: 'The single objective for the Sprint', explain: 'It is a commitment that provides flexibility in exact work.' },
  { id: 'z-sc-30', topic: 'SC', q: 'When is a Product Increment "born"?', options: ['The moment a Product Backlog item meets the Definition of Done', 'At Sprint Planning', 'At the Sprint Review', 'When added to the backlog'], correct: 'The moment a Product Backlog item meets the Definition of Done', explain: 'An increment exists once a PBI satisfies the DoD.' },
  { id: 'z-sc-31', topic: 'SC', q: 'What happens to a PBI that does not meet the Definition of Done?', options: ['It returns to the Product Backlog; it cannot be released or shown at the Review', 'It is deployed anyway', 'It is deleted permanently', 'It is escalated to the Sponsor'], correct: 'It returns to the Product Backlog; it cannot be released or shown at the Review', explain: 'Only "Done" work can be released or presented.' },
  { id: 'z-sc-32', topic: 'SC', q: 'How do Schwaber and Sutherland famously describe Scrum?', options: ['"Lightweight, simple to understand, difficult to master"', '"Heavyweight but reliable"', '"A complete methodology"', '"A documentation framework"'], correct: '"Lightweight, simple to understand, difficult to master"', explain: 'A well-known description of Scrum.' },
  { id: 'z-sc-33', topic: 'SC', q: 'Why does AgilePM describe Scrum\'s structure as "fixed"?', options: ['Its roles, artefacts, events and rules must all be present and followed', 'Because Sprints never change length', 'Because the Product Owner cannot change', 'Because the budget is fixed'], correct: 'Its roles, artefacts, events and rules must all be present and followed', explain: 'Removing a Scrum element means you are not really doing Scrum.' },
  { id: 'z-sc-34', topic: 'SC', q: 'What term does AgilePM v3 use instead of Scrum\'s "Increment"?', options: ['Product Increment', 'Solution Artifact', 'Deliverable', 'Work-product'], correct: 'Product Increment', explain: 'AgilePM v3 uses "Product Increment" for clarity.' },
  { id: 'z-sc-35', topic: 'SC', q: 'In the Scrum "nutshell", what does the Scrum Team turn a selection of work into during a Sprint?', options: ['An Increment of value', 'A signed contract', 'A detailed specification', 'A status report'], correct: 'An Increment of value', explain: 'The team turns ordered work into a valuable increment each Sprint.' },
  { id: 'z-sc-36', topic: 'SC', q: 'Who creates the Sprint Backlog?', options: ['The Developers', 'The Product Owner', 'The Scrum Master', 'The Business Visionary'], correct: 'The Developers', explain: 'It is created by the Developers, for the Developers.' },

  // ===================================================================
  // AF — AgilePM Fundamentals
  // ===================================================================
  { id: 'z-af-1', topic: 'AF', q: 'What is the AgilePM Philosophy?', options: ['Best value emerges when projects align to clear goals, deliver frequently and involve motivated, empowered people', 'Deliver everything the customer asks for, whatever the cost', 'Follow the plan exactly, regardless of change', 'Maximise documentation and sign-off'], correct: 'Best value emerges when projects align to clear goals, deliver frequently and involve motivated, empowered people', explain: 'This is the AgilePM Philosophy statement.' },
  { id: 'z-af-2', topic: 'AF', q: 'What are the four foundational elements of the AgilePM Framework?', options: ['Process, People, Project Artifacts, Practices', 'Time, Cost, Quality, Features', 'Plan, Build, Test, Deploy', 'Vision, Backlog, Sprint, Review'], correct: 'Process, People, Project Artifacts, Practices', explain: 'The four framework elements.' },
  { id: 'z-af-3', topic: 'AF', q: 'What underpins all of AgilePM beneath the framework?', options: ['Common sense and pragmatism', 'Documentation and audit', 'Contracts and governance', 'Velocity and burn-down'], correct: 'Common sense and pragmatism', explain: 'Logical judgment and adapting to real situations.' },
  { id: 'z-af-4', topic: 'AF', q: 'What are the four Project Variables in AgilePM?', options: ['Time, Cost, Quality, Features', 'Scope, Schedule, Budget, Risk', 'People, Process, Product, Practice', 'Vision, Value, Velocity, Volume'], correct: 'Time, Cost, Quality, Features', explain: 'The four project variables.' },
  { id: 'z-af-5', topic: 'AF', q: 'In the AgilePM approach, which variables are FIXED?', options: ['Time, Cost and Quality', 'Features only', 'Features and Time', 'Quality and Features'], correct: 'Time, Cost and Quality', explain: 'AgilePM fixes Time, Cost, Quality and varies Features.' },
  { id: 'z-af-6', topic: 'AF', q: 'Which variable does AgilePM allow to VARY?', options: ['Features', 'Quality', 'Time', 'Cost'], correct: 'Features', explain: 'Features flex via MoSCoW; the rest are fixed.' },
  { id: 'z-af-7', topic: 'AF', q: 'In a traditional/sequential approach, which variable is fixed?', options: ['Features', 'Time', 'Cost', 'Quality'], correct: 'Features', explain: 'Traditionally features are fixed and time/cost vary (quality often slips).' },
  { id: 'z-af-8', topic: 'AF', q: 'How is contingency provided by default in AgilePM?', options: ['Through MoSCoW prioritisation of scope', 'Through extra budget set aside', 'Through extending deadlines', 'Through reducing quality'], correct: 'Through MoSCoW prioritisation of scope', explain: 'Flexing scope (not time/cost/quality) provides contingency.' },
  { id: 'z-af-9', topic: 'AF', q: 'What is Parkinson\'s Law?', options: ['Work expands to fill the time available', 'Cost rises to meet the budget', 'Quality falls under pressure', 'Scope grows to match the team'], correct: 'Work expands to fill the time available', explain: 'A reason teams hesitate to set aside formal time contingency.' },
  { id: 'z-af-10', topic: 'AF', q: 'How many AgilePM principles are there?', options: ['8', '12', '5', '9'], correct: '8', explain: 'There are 8 AgilePM principles.' },
  { id: 'z-af-11', topic: 'AF', q: 'Which is AgilePM Principle 1?', options: ['Focus on the Business Need', 'Deliver on Time', 'Never Compromise Quality', 'Demonstrate Control'], correct: 'Focus on the Business Need', explain: 'Principle 1: Focus on the Business Need.' },
  { id: 'z-af-12', topic: 'AF', q: 'Which AgilePM principle covers building strong foundations before major development?', options: ['Build Incrementally from Firm Foundations', 'Develop Iteratively', 'Demonstrate Control', 'Collaborate'], correct: 'Build Incrementally from Firm Foundations', explain: 'Principle 5: Build Incrementally from Firm Foundations.' },
  { id: 'z-af-13', topic: 'AF', q: 'Under AgilePM, who does NOT create the Business Case (but must ensure it gets attention)?', options: ['The Project Manager', 'The Business Visionary', 'The Business Sponsor', 'The Solution Architect'], correct: 'The Project Manager', explain: 'Value Ownership roles own the Business Case; the PM ensures attention.' },
  { id: 'z-af-14', topic: 'AF', q: 'Who is responsible for setting the Definition of Done in AgilePM?', options: ['The Solution Architect', 'The Project Manager', 'The Business Sponsor', 'The Scrum Master'], correct: 'The Solution Architect', explain: 'The Solution Architect sets the DoD and quality standards.' },
  { id: 'z-af-15', topic: 'AF', q: 'When should the expected quality level be defined?', options: ['At the beginning of the project', 'At the end of Delivery', 'During Deployment', 'Only if an audit requires it'], correct: 'At the beginning of the project', explain: 'Quality is fit-for-purpose, defined up front.' },
  { id: 'z-af-16', topic: 'AF', q: 'What are the five AgilePM Practices?', options: ['Iterative Development, Timeboxing, MoSCoW, Modelling, Facilitated Workshops', 'Planning Poker, Velocity, Burn-down, Kanban, DevOps', 'Vision, Backlog, Sprint, Review, Retro', 'RACI, PAQ, SAD, DAD, MAD'], correct: 'Iterative Development, Timeboxing, MoSCoW, Modelling, Facilitated Workshops', explain: 'The five practices that enable the principles.' },
  { id: 'z-af-17', topic: 'AF', q: 'What does MoSCoW stand for?', options: ['Must Have, Should Have, Could Have, Won\'t Have this time', 'Must, Selected, Critical, Wanted', 'Mandatory, Secondary, Conditional, Waived', 'Most, Some, Couple, Without'], correct: 'Must Have, Should Have, Could Have, Won\'t Have this time', explain: 'The capital letters spell the four priorities.' },
  { id: 'z-af-18', topic: 'AF', q: 'What "culture" should AgilePM build (Principle 3 — Collaborate)?', options: ['A "one-team" culture focused on success of the whole Project Organisation', 'A competitive culture between teams', 'A documentation-first culture', 'A command-and-control culture'], correct: 'A "one-team" culture focused on success of the whole Project Organisation', explain: 'Collaboration creates shared ownership.' },
  { id: 'z-af-19', topic: 'AF', q: 'Under "Demonstrate Control", how should progress be measured?', options: ['Based on product delivery (working solutions), not just completed activities', 'By percentage of tasks ticked off', 'By hours worked', 'By documents produced'], correct: 'Based on product delivery (working solutions), not just completed activities', explain: 'A partially complete feature has less value than one not started.' },
  { id: 'z-af-20', topic: 'AF', q: 'Why should reports not be solely relied upon for governance (Demonstrate Control)?', options: ['They can be outdated and miss details visible in direct project work', 'They are always inaccurate', 'They take too long to write', 'They are confidential'], correct: 'They can be outdated and miss details visible in direct project work', explain: 'Transparency of actual work beats stale reports.' },
  { id: 'z-af-21', topic: 'AF', q: 'Under what conditions should documentation be created (Principle 7)?', options: ['Only if it adds value, aids development/support, or is needed for safety/compliance', 'Always, for every decision', 'Never, under any circumstances', 'Only at the end of the project'], correct: 'Only if it adds value, aids development/support, or is needed for safety/compliance', explain: 'Documentation is justified by value or compliance.' },
  { id: 'z-af-22', topic: 'AF', q: 'AgilePM Principle 2 is "Deliver on Time". Why is on-time delivery critical?', options: ['A delayed Solution Increment can lose its value (e.g. market or legal deadlines)', 'It looks good on reports', 'It reduces the team size', 'It avoids any testing'], correct: 'A delayed Solution Increment can lose its value (e.g. market or legal deadlines)', explain: 'Value can be time-sensitive.' },
  { id: 'z-af-23', topic: 'AF', q: 'What does AgilePM with Scrum add that pure Scrum lacks?', options: ['A project lifecycle with appropriate governance and additional value-ownership roles', 'A way to write code faster', 'Mandatory fixed-price contracts', 'A replacement for the Product Owner'], correct: 'A project lifecycle with appropriate governance and additional value-ownership roles', explain: 'AgilePM wraps Scrum in project-level governance and roles.' },
  { id: 'z-af-24', topic: 'AF', q: 'Define "pragmatism" in the AgilePM context.', options: ['Making decisions that adapt to real-life situations rather than following rigid rules', 'Always following the documented process', 'Avoiding all risk', 'Maximising paperwork'], correct: 'Making decisions that adapt to real-life situations rather than following rigid rules', explain: 'Pragmatism adapts to reality.' },
  { id: 'z-af-25', topic: 'AF', q: 'What four conditions must be true for every stakeholder (AgilePM Philosophy)?', options: ['Understands the vision, is empowered, collaborates on the solution and on-time delivery, and accepts change', 'Signs the contract, approves the budget, attends meetings, writes reports', 'Avoids decisions, defers to managers, follows the plan, minimises risk', 'Owns the backlog, runs the Sprints, sets the DoD, deploys the solution'], correct: 'Understands the vision, is empowered, collaborates on the solution and on-time delivery, and accepts change', explain: 'These conditions underpin the philosophy.' },
  { id: 'z-af-26', topic: 'AF', q: 'How does AgilePM help the Product Owner?', options: ['It provides business, user and corporate context for decision-making', 'It writes the code for them', 'It removes the need for a backlog', 'It sets their salary'], correct: 'It provides business, user and corporate context for decision-making', explain: 'AgilePM keeps product decisions aligned to business goals.' },
  { id: 'z-af-27', topic: 'AF', q: 'What can AgilePM manage that pure Scrum cannot easily handle?', options: ['Business-related work not directly linked to product development (e.g. business process change)', 'Writing user stories', 'Running Daily Scrums', 'Estimating story points'], correct: 'Business-related work not directly linked to product development (e.g. business process change)', explain: 'AgilePM extends beyond product development.' },
  { id: 'z-af-28', topic: 'AF', q: 'Which AgilePM principle is "Never Compromise Quality"?', options: ['Principle 4', 'Principle 2', 'Principle 6', 'Principle 8'], correct: 'Principle 4', explain: 'Principle 4: Never Compromise Quality.' },
  { id: 'z-af-29', topic: 'AF', q: 'Which AgilePM principle is "Develop Iteratively"?', options: ['Principle 6', 'Principle 3', 'Principle 5', 'Principle 7'], correct: 'Principle 6', explain: 'Principle 6: Develop Iteratively.' },
  { id: 'z-af-30', topic: 'AF', q: 'Which AgilePM principle is "Communicate Continuously and Clearly"?', options: ['Principle 7', 'Principle 1', 'Principle 4', 'Principle 8'], correct: 'Principle 7', explain: 'Principle 7: Communicate Continuously and Clearly.' },

  // ===================================================================
  // IN — Individuals & Interactions
  // ===================================================================
  { id: 'z-in-1', topic: 'IN', q: 'What are the three Project Role domains AgilePM defines?', options: ['Value Ownership, Solution Delivery, Delivery Enablement', 'Business, Technical, Governance', 'Sponsor, Visionary, Architect', 'Plan, Build, Run'], correct: 'Value Ownership, Solution Delivery, Delivery Enablement', explain: 'The three role domains.' },
  { id: 'z-in-2', topic: 'IN', q: 'Which roles sit in the Value Ownership domain?', options: ['Business Sponsor and Business Visionary', 'Solution Architect and Developers', 'Project Manager and Scrum Master', 'Product Owner and Developers'], correct: 'Business Sponsor and Business Visionary', explain: 'Value Ownership = Business Sponsor + Business Visionary.' },
  { id: 'z-in-3', topic: 'IN', q: 'Which Project Role is in the Solution Delivery domain?', options: ['The Solution Architect', 'The Business Sponsor', 'The Project Manager', 'The Business Visionary'], correct: 'The Solution Architect', explain: 'Solution Delivery = Solution Architect (Scrum: Developers).' },
  { id: 'z-in-4', topic: 'IN', q: 'Which Project Role is in the Delivery Enablement domain?', options: ['The Project Manager', 'The Solution Architect', 'The Business Sponsor', 'The Product Owner'], correct: 'The Project Manager', explain: 'Delivery Enablement = Project Manager (Scrum: Scrum Master).' },
  { id: 'z-in-5', topic: 'IN', q: 'Who is the Business Sponsor?', options: ['The Project Champion who owns the Business Case and holds the budget', 'The person who writes code', 'The independent workshop facilitator', 'The regulatory auditor'], correct: 'The Project Champion who owns the Business Case and holds the budget', explain: 'The Sponsor is the final authority on critical decisions.' },
  { id: 'z-in-6', topic: 'IN', q: 'Can the Business Sponsor role be shared?', options: ['No — it is always fulfilled by a single person', 'Yes — by any number of people', 'Yes — split equally across the team', 'Only if the Sprint is cancelled'], correct: 'No — it is always fulfilled by a single person', explain: 'It may represent a governing group, but is one person.' },
  { id: 'z-in-7', topic: 'IN', q: 'Who acts like the overall Product Owner for the project solution?', options: ['The Business Visionary', 'The Project Manager', 'The Solution Architect', 'The Scrum Master'], correct: 'The Business Visionary', explain: 'The Visionary captures and communicates the project vision.' },
  { id: 'z-in-8', topic: 'IN', q: 'Who owns the solution design and sets the Definition of Done?', options: ['The Solution Architect', 'The Business Visionary', 'The Project Manager', 'The Product Owner'], correct: 'The Solution Architect', explain: 'The SA owns the architecture and delivery approach.' },
  { id: 'z-in-9', topic: 'IN', q: 'What does the Project Manager make decisions about?', options: ['How the project is managed', 'Business-value decisions', 'The integrity of the solution', 'The Product Backlog order'], correct: 'How the project is managed', explain: 'PM decides on delivery enablement / project management.' },
  { id: 'z-in-10', topic: 'IN', q: 'Which three Project Roles hold the same level of authority?', options: ['Business Sponsor, Business Visionary, Solution Architect', 'Project Manager, Scrum Master, Product Owner', 'Developers, Advisors, Stakeholders', 'Business Sponsor, Project Manager, Scrum Master'], correct: 'Business Sponsor, Business Visionary, Solution Architect', explain: 'These three hold the same level of authority.' },
  { id: 'z-in-11', topic: 'IN', q: 'What are the three Advisor Roles?', options: ['Business Advisor, Solution Advisor, Process Advisor', 'Sponsor, Visionary, Architect', 'Analyst, Tester, Designer', 'Coach, Mentor, Trainer'], correct: 'Business Advisor, Solution Advisor, Process Advisor', explain: 'The three advisor roles.' },
  { id: 'z-in-12', topic: 'IN', q: 'A typical example of a Process Advisor is...', options: ['An Agile Coach or Workshop Facilitator', 'A Business Sponsor', 'A Developer', 'A regulator'], correct: 'An Agile Coach or Workshop Facilitator', explain: 'Process Advisors provide agile-framework expertise.' },
  { id: 'z-in-13', topic: 'IN', q: 'Can a single person fulfil more than one AgilePM role?', options: ['Yes — roles do not necessarily equate to people', 'No — one person per role always', 'Only the Scrum Master can', 'Only in the Feasibility Phase'], correct: 'Yes — roles do not necessarily equate to people', explain: 'Roles can be shared or combined.' },
  { id: 'z-in-14', topic: 'IN', q: 'What does the first principle of Agile Leadership state?', options: ['Leadership lives everywhere in the organisation', 'Leaders must always decide quickly', 'Only managers can lead', 'Leadership requires authority'], correct: 'Leadership lives everywhere in the organisation', explain: 'Leadership emerges based on expertise and initiative.' },
  { id: 'z-in-15', topic: 'IN', q: 'Agile leaders aim to develop...', options: ['New leaders, not followers', 'More detailed documentation', 'Tighter control over teams', 'Larger teams'], correct: 'New leaders, not followers', explain: 'They build leadership capability in others.' },
  { id: 'z-in-16', topic: 'IN', q: 'On a leadership spectrum, "Do whatever you think is best" describes which style?', options: ['Servant leadership', 'Command-and-control', 'Bureaucratic', 'Authoritarian'], correct: 'Servant leadership', explain: 'Servant leadership is one end; command-and-control the other.' },
  { id: 'z-in-17', topic: 'IN', q: 'What are Geoff Watts\' two "commandments" of a Scrum Master?', options: ['First ask the team; make yourself redundant', 'Plan everything; control the team', 'Document all; report often', 'Estimate first; deliver later'], correct: 'First ask the team; make yourself redundant', explain: 'Defer to the team and build self-reliance.' },
  { id: 'z-in-18', topic: 'IN', q: 'What does "True Leadership" mean per the Scrum Guide?', options: ['Success is defined by the effectiveness of the team; it comes from developing others', 'Success means hitting the deadline alone', 'Success is measured by documentation', 'Success means controlling decisions'], correct: 'Success is defined by the effectiveness of the team; it comes from developing others', explain: 'True/servant leaders grow their teams.' },
  { id: 'z-in-19', topic: 'IN', q: 'Who decides HOW the work will be done in a Scrum Team?', options: ['The Developers', 'The Product Owner', 'The Scrum Master', 'The Project Manager'], correct: 'The Developers', explain: 'Developers decide how to build the increment.' },
  { id: 'z-in-20', topic: 'IN', q: 'Why is the title "Developer" used despite teams being cross-functional?', options: ['"We use the word developers not to exclude, but to simplify"', 'Because everyone writes code', 'To match HR job titles', 'To reduce team size'], correct: '"We use the word developers not to exclude, but to simplify"', explain: 'Developers have varied skills, knowledge and experience.' },
  { id: 'z-in-21', topic: 'IN', q: 'Who is responsible for the realisation (embedding) of benefits?', options: ['The Business Visionary', 'The Project Manager', 'The Scrum Master', 'The Developers'], correct: 'The Business Visionary', explain: 'The Visionary embeds the solution; the Sponsor owns the RoI.' },
  { id: 'z-in-22', topic: 'IN', q: 'Who is accountable for the return on investment?', options: ['The Business Sponsor', 'The Business Visionary', 'The Solution Architect', 'The Product Owner'], correct: 'The Business Sponsor', explain: 'The Sponsor is accountable for RoI.' },
  { id: 'z-in-23', topic: 'IN', q: 'Who are "External Stakeholders"?', options: ['People outside the project organisation but who influence it or are affected by the solution', 'Only customers who buy the product', 'Only government regulators', 'Members of the Delivery Team'], correct: 'People outside the project organisation but who influence it or are affected by the solution', explain: 'They can be internal or external to the wider organisation.' },
  { id: 'z-in-24', topic: 'IN', q: 'How many Delivery Teams might an experienced Product Owner support (sharing one Product Backlog)?', options: ['Up to 3', 'Exactly 1', 'Up to 10', 'Unlimited'], correct: 'Up to 3', explain: 'Good practice suggests up to ~3 teams sharing a single Product Backlog.' },
  { id: 'z-in-25', topic: 'IN', q: 'A Scrum Master may effectively support up to how many teams?', options: ['Three teams', 'One team', 'Five teams', 'Ten teams'], correct: 'Three teams', explain: 'A Scrum Master can support up to three teams.' },
  { id: 'z-in-26', topic: 'IN', q: 'What does the Solution Architect balance?', options: ['The Business Visionary\'s ambitions so the solution is realistic and feasible', 'The project budget against the schedule', 'The team\'s holidays', 'The number of Sprints'], correct: 'The Business Visionary\'s ambitions so the solution is realistic and feasible', explain: 'The SA keeps the solution feasible.' },
  { id: 'z-in-27', topic: 'IN', q: 'What does a Business Advisor primarily do?', options: ['Provide specialist business input on requirements, decisions and regulatory compliance', 'Write the code', 'Facilitate the Daily Scrum', 'Own the project budget'], correct: 'Provide specialist business input on requirements, decisions and regulatory compliance', explain: 'Business Advisors collaborate with value ownership roles.' },
  { id: 'z-in-28', topic: 'IN', q: 'A person fulfilling a Solution Advisor role in Feasibility may later become...', options: ['A Developer in a Delivery Team', 'The Business Sponsor', 'The Project Manager', 'An auditor'], correct: 'A Developer in a Delivery Team', explain: 'Solution Advisors collaborate with solution delivery roles.' },
  { id: 'z-in-29', topic: 'IN', q: 'Who corresponds to the Scrum Master in earlier versions of AgilePM?', options: ['The Team Leader', 'The Project Manager', 'The Solution Architect', 'The Business Visionary'], correct: 'The Team Leader', explain: 'The SM fits Delivery Enablement, corresponding with Team Leader.' },
  { id: 'z-in-30', topic: 'IN', q: 'What does the Value Ownership domain concern?', options: ['Representing organisation, customer and user stakeholders so needs are reflected in the solution', 'Building the technical architecture', 'Running the Sprints', 'Auditing compliance'], correct: 'Representing organisation, customer and user stakeholders so needs are reflected in the solution', explain: 'Value Ownership ensures needs are managed.' },
  { id: 'z-in-31', topic: 'IN', q: 'What does the Delivery Enablement domain concern?', options: ['Leading the project as defined by the AgilePM approach', 'Designing the solution', 'Owning the Business Case', 'Writing user stories'], correct: 'Leading the project as defined by the AgilePM approach', explain: 'Delivery Enablement = leading/managing the project (PM).' },
  { id: 'z-in-32', topic: 'IN', q: 'Who must empower the other Project Roles to deliver a valuable solution?', options: ['The Business Sponsor', 'The Scrum Master', 'The Developers', 'The Product Owner'], correct: 'The Business Sponsor', explain: 'The Sponsor empowers the other roles.' },
  { id: 'z-in-33', topic: 'IN', q: 'Explain "First ask the team" (Watts).', options: ['Default to asking the team for solutions because they have the knowledge and context', 'Always give the team your own answer first', 'Ask the Sponsor before the team', 'Ask the auditor first'], correct: 'Default to asking the team for solutions because they have the knowledge and context', explain: 'Resist jumping in with your own answers.' },
  { id: 'z-in-34', topic: 'IN', q: 'What role might a Business Analyst take within a Delivery Team?', options: ['Work as a Developer, heavily supporting Product Backlog management', 'Always act as the Product Owner', 'Replace the Scrum Master', 'Own the Business Case'], correct: 'Work as a Developer, heavily supporting Product Backlog management', explain: 'AgilePM recognises the BA as a Developer in some contexts.' },
  { id: 'z-in-35', topic: 'IN', q: 'At the Strategic level, a Business Analyst assists with...', options: ['Defining and shaping business strategies impacting the whole organisation', 'Writing acceptance criteria for one story', 'Running the Daily Scrum', 'Booking facilities'], correct: 'Defining and shaping business strategies impacting the whole organisation', explain: 'Strategic-level BA work supports executives.' },
  { id: 'z-in-36', topic: 'IN', q: 'What four factors influence how external stakeholders interact with a project?', options: ['Purpose, Timing, Authority, Constraints', 'Power, Interest, Budget, Skill', 'Vision, Value, Velocity, Volume', 'Cost, Time, Quality, Risk'], correct: 'Purpose, Timing, Authority, Constraints', explain: 'These four factors shape external stakeholder engagement.' },
  { id: 'z-in-37', topic: 'IN', q: 'What should the Business Visionary and Solution Architect do regarding external stakeholders?', options: ['Manage relationships and coordinate decision-making, facilitated by the Project Manager', 'Ignore them until Deployment', 'Delegate entirely to the auditor', 'Replace them with documentation'], correct: 'Manage relationships and coordinate decision-making, facilitated by the Project Manager', explain: 'The PM facilitates these relationships.' },
  { id: 'z-in-38', topic: 'IN', q: 'What does the Business Sponsor own besides the Business Case?', options: ['The Solution Backlog (if used)', 'The Sprint Backlog', 'The Definition of Done', 'The Product Increment'], correct: 'The Solution Backlog (if used)', explain: 'The Sponsor owns the project and the Solution Backlog if used.' },

  // ===================================================================
  // CC — Collaboration & Communication
  // ===================================================================
  { id: 'z-cc-1', topic: 'CC', q: 'Which two AgilePM principles relate directly to collaboration and communication?', options: ['Principle 3 (Collaborate) and Principle 7 (Communicate Continuously and Clearly)', 'Principle 1 and Principle 2', 'Principle 4 and Principle 8', 'Principle 5 and Principle 6'], correct: 'Principle 3 (Collaborate) and Principle 7 (Communicate Continuously and Clearly)', explain: 'Principles 3 and 7.' },
  { id: 'z-cc-2', topic: 'CC', q: 'How is Collaboration defined?', options: ['Working together towards a shared goal in a project', 'Signing a contract', 'Writing a specification', 'Reporting to management'], correct: 'Working together towards a shared goal in a project', explain: 'Within a team and across parties.' },
  { id: 'z-cc-3', topic: 'CC', q: 'How is Communication defined?', options: ['The exchange of thoughts, opinions or information between people', 'The signing of documents', 'The production of reports', 'The approval of budgets'], correct: 'The exchange of thoughts, opinions or information between people', explain: 'Through speech, writing, symbols, images, gestures or behaviour.' },
  { id: 'z-cc-4', topic: 'CC', q: 'According to Manifesto Principle 6, the most efficient method of conveying information is...', options: ['Face-to-face conversation', 'Email', 'Detailed documentation', 'Recorded video'], correct: 'Face-to-face conversation', explain: 'Face-to-face is richest (tone and body language).' },
  { id: 'z-cc-5', topic: 'CC', q: 'What is email best used for?', options: ['Confirming previous discussions', 'Replacing all face-to-face meetings', 'Resolving complex disputes', 'Running workshops'], correct: 'Confirming previous discussions', explain: 'Email confirms; it should not be the primary channel.' },
  { id: 'z-cc-6', topic: 'CC', q: 'On the Power/Interest Grid, High Power / High Interest stakeholders should be...', options: ['Closely engaged', 'Kept satisfied', 'Kept informed', 'Monitored'], correct: 'Closely engaged', explain: 'High power + high interest = closely engage.' },
  { id: 'z-cc-7', topic: 'CC', q: 'On the Power/Interest Grid, High Power / Low Interest stakeholders should be...', options: ['Kept satisfied', 'Closely engaged', 'Kept informed', 'Monitored'], correct: 'Kept satisfied', explain: 'High power + low interest = keep satisfied.' },
  { id: 'z-cc-8', topic: 'CC', q: 'On the Power/Interest Grid, Low Power / High Interest stakeholders should be...', options: ['Kept informed', 'Closely engaged', 'Kept satisfied', 'Monitored'], correct: 'Kept informed', explain: 'Low power + high interest = keep informed.' },
  { id: 'z-cc-9', topic: 'CC', q: 'On the Power/Interest Grid, Low Power / Low Interest stakeholders should be...', options: ['Monitored (minimum effort)', 'Closely engaged', 'Kept satisfied', 'Kept informed'], correct: 'Monitored (minimum effort)', explain: 'Low power + low interest = monitor.' },
  { id: 'z-cc-10', topic: 'CC', q: 'What are the four benefits of collaboration?', options: ['Improved problem-solving, learning, productivity and cross-functional learning', 'More documentation, contracts, reports and audits', 'Faster typing, coding, testing and deploying', 'Lower cost, time, risk and scope'], correct: 'Improved problem-solving, learning, productivity and cross-functional learning', explain: 'The four collaboration benefits.' },
  { id: 'z-cc-11', topic: 'CC', q: 'What three elements does a Facilitated Workshop require?', options: ['A workshop owner, selected participants, and an independent facilitator', 'A contract, a budget and an auditor', 'A backlog, a Sprint and a review', 'A sponsor, a visionary and an architect'], correct: 'A workshop owner, selected participants, and an independent facilitator', explain: 'The facilitator (a Process Advisor) ensures the outcome.' },
  { id: 'z-cc-12', topic: 'CC', q: 'What is Modelling?', options: ['A method of visually representing a problem or solution', 'A way to write contracts', 'A budgeting technique', 'A testing strategy'], correct: 'A method of visually representing a problem or solution', explain: 'Models make things easier to understand.' },
  { id: 'z-cc-13', topic: 'CC', q: 'What is "Team Collaboration"?', options: ['Working in a group where members understand each other\'s skills to achieve a common goal', 'Knowledge sharing across the whole project community', 'Collaboration with regulators', 'Contract negotiation'], correct: 'Working in a group where members understand each other\'s skills to achieve a common goal', explain: 'Shared responsibility, mutual support.' },
  { id: 'z-cc-14', topic: 'CC', q: 'What is "Community Collaboration"?', options: ['Knowledge-sharing and unity across the whole project, regardless of org boundaries', 'Working only within one team', 'Negotiating contracts', 'Auditing compliance'], correct: 'Knowledge-sharing and unity across the whole project, regardless of org boundaries', explain: 'It rewards the collective efforts of the whole community.' },
  { id: 'z-cc-15', topic: 'CC', q: 'What does Jim Highsmith\'s quote state?', options: ['"Documentation is not understanding, process is not discipline, formality is not skill"', '"Move fast and break things"', '"Done is better than perfect"', '"The plan is everything"'], correct: '"Documentation is not understanding, process is not discipline, formality is not skill"', explain: 'A reminder to focus on real understanding.' },
  { id: 'z-cc-16', topic: 'CC', q: 'What is Active Listening?', options: ['Pay attention, show you are listening, defer judgment, then respond appropriately', 'Interrupt to give your view quickly', 'Take notes silently and never respond', 'Reply by email afterwards'], correct: 'Pay attention, show you are listening, defer judgment, then respond appropriately', explain: 'A core communication soft skill.' },
  { id: 'z-cc-17', topic: 'CC', q: 'What can over-using technology for communication lead to?', options: ['Reduced effectiveness due to missing body language and tone', 'Perfect clarity always', 'Faster contract sign-off', 'Better governance'], correct: 'Reduced effectiveness due to missing body language and tone', explain: 'Replacing face-to-face with email/chat causes misunderstandings.' },
  { id: 'z-cc-18', topic: 'CC', q: 'How can diverse teams avoid misunderstandings from technical jargon?', options: ['Use common, straightforward language and keep a glossary of key terms', 'Ban all technical terms', 'Only communicate in writing', 'Avoid cross-functional work'], correct: 'Use common, straightforward language and keep a glossary of key terms', explain: 'A glossary helps shared understanding.' },
  { id: 'z-cc-19', topic: 'CC', q: 'On the Aligned Autonomy Matrix, High Alignment / High Autonomy describes which organisation?', options: ['Innovative (Collaborative Culture)', 'Authoritative (Authoritarian Culture)', 'Bureaucratic (Indifferent Culture)', 'Entrepreneurial (Chaotic Culture)'], correct: 'Innovative (Collaborative Culture)', explain: 'High alignment + high autonomy = innovative/collaborative.' },
  { id: 'z-cc-20', topic: 'CC', q: 'Virtual meetings are most effective when...', options: ['Video and audio quality are reliable (prefer video over audio-only)', 'Only audio is used', 'They replace every face-to-face interaction', 'Cameras are always off'], correct: 'Video and audio quality are reliable (prefer video over audio-only)', explain: 'Video conveys some body language; quality matters.' },
  { id: 'z-cc-21', topic: 'CC', q: 'What is a key risk of documenting too many details when planning communications?', options: ['It creates a false sense of certainty in uncertain situations', 'It always improves accuracy', 'It removes the need to talk', 'It guarantees compliance'], correct: 'It creates a false sense of certainty in uncertain situations', explain: 'Excessive paperwork can mislead in VUCA.' },
  { id: 'z-cc-22', topic: 'CC', q: 'What should leaders focus on when mistakes happen?', options: ['Learning, not blaming individuals', 'Identifying who to punish', 'Adding more documentation', 'Reducing team autonomy'], correct: 'Learning, not blaming individuals', explain: 'Learning culture strengthens trust and teamwork.' },
  { id: 'z-cc-23', topic: 'CC', q: 'Which Scrum Value means "the team and stakeholders agree to openly share information and challenges"?', options: ['Openness', 'Focus', 'Courage', 'Respect'], correct: 'Openness', explain: 'Openness supports collaboration.' },
  { id: 'z-cc-24', topic: 'CC', q: 'Why should facilitated workshops and modelling be used?', options: ['To prioritise people and communication over rigid processes and tools', 'To produce maximum documentation', 'To enforce contracts', 'To avoid customer involvement'], correct: 'To prioritise people and communication over rigid processes and tools', explain: 'They help teams reach shared understanding.' },
  { id: 'z-cc-25', topic: 'CC', q: 'Why is a verbal commitment in a group sometimes stronger than a signed document?', options: ['The shared, public nature reinforces the commitment', 'Documents are never valid', 'Verbal commitments are legally binding', 'It avoids governance'], correct: 'The shared, public nature reinforces the commitment', explain: 'Shared understanding matters more than the paperwork itself.' },
  { id: 'z-cc-26', topic: 'CC', q: 'What is the main goal of any document in AgilePM?', options: ['To ensure everyone has a shared understanding of its content', 'To satisfy an auditor regardless of value', 'To replace conversations entirely', 'To assign blame'], correct: 'To ensure everyone has a shared understanding of its content', explain: 'Shared understanding is the point, not the document.' },

  // ===================================================================
  // PR — Project Lifecycle Framework
  // ===================================================================
  { id: 'z-pr-1', topic: 'PR', q: 'What are the six phases of the AgilePM Process Model?', options: ['Pre-Project, Feasibility, Foundations, Delivery, Deployment, Realisation', 'Initiation, Planning, Execution, Monitoring, Closing, Review', 'Vision, Backlog, Sprint, Review, Retro, Release', 'Discover, Define, Design, Develop, Deploy, Decommission'], correct: 'Pre-Project, Feasibility, Foundations, Delivery, Deployment, Realisation', explain: 'The six AgilePM phases.' },
  { id: 'z-pr-2', topic: 'PR', q: 'What is the purpose of the Pre-Project Phase?', options: ['Decide whether there is value in investigating a project further', 'Build the solution', 'Deploy the solution', 'Measure benefits'], correct: 'Decide whether there is value in investigating a project further', explain: 'It gets approval for a small initial investigation.' },
  { id: 'z-pr-3', topic: 'PR', q: 'What is the recommended Project Artifact of the Pre-Project Phase?', options: ['Terms of Reference', 'Business Case', 'Delivery Plan', 'Foundations Summary'], correct: 'Terms of Reference', explain: 'The Terms of Reference is a short milestone artifact.' },
  { id: 'z-pr-4', topic: 'PR', q: 'What is the purpose of the Feasibility Phase?', options: ['A high-level assessment of whether the project is desirable, feasible and viable', 'Detailed build of the solution', 'Final deployment', 'Benefits realisation'], correct: 'A high-level assessment of whether the project is desirable, feasible and viable', explain: 'It keeps things light to decide go/no-go.' },
  { id: 'z-pr-5', topic: 'PR', q: 'What rough estimate accuracy is appropriate during Feasibility?', options: ['Around +/- 50%', 'Exact to the day', '+/- 5%', '+/- 1%'], correct: 'Around +/- 50%', explain: 'Only rough ranges are needed at Feasibility.' },
  { id: 'z-pr-6', topic: 'PR', q: 'What does the Foundations Phase focus on?', options: ['Three key areas: Value, Solution and Process', 'Only the budget', 'Only the technical design', 'Only deployment'], correct: 'Three key areas: Value, Solution and Process', explain: 'Foundations establishes firm foundations across these areas.' },
  { id: 'z-pr-7', topic: 'PR', q: 'How long should the Foundations Phase typically last, even for large projects?', options: ['Only a few weeks', 'Several months', 'Half the project', 'As long as Delivery'], correct: 'Only a few weeks', explain: 'Keeping it high-level avoids delays.' },
  { id: 'z-pr-8', topic: 'PR', q: 'Which Project Artifact is REQUIRED and produced at the end of the Foundations Phase?', options: ['The Delivery Plan', 'The Benefits Assessment', 'The Terms of Reference', 'The Sprint Review Record'], correct: 'The Delivery Plan', explain: 'The Delivery Plan is a required artifact.' },
  { id: 'z-pr-9', topic: 'PR', q: 'What is the purpose of the Delivery Phase?', options: ['Create and incrementally deliver Product and Solution Increments to realise value', 'Decide whether to start the project', 'Measure long-term benefits', 'Write the Business Case'], correct: 'Create and incrementally deliver Product and Solution Increments to realise value', explain: 'Delivery builds and delivers increments.' },
  { id: 'z-pr-10', topic: 'PR', q: 'What is the purpose of the Deployment Phase?', options: ['Release the solution (or part) into operational use until a steady state', 'Investigate feasibility', 'Refine the Business Case', 'Run retrospectives'], correct: 'Release the solution (or part) into operational use until a steady state', explain: 'Deployment reaches a point of consistent business value.' },
  { id: 'z-pr-11', topic: 'PR', q: 'What is the purpose of the Realisation Phase?', options: ['Ensure the expected benefits of the solution actually happen over time', 'Build the solution', 'Approve the budget', 'Run Sprint Planning'], correct: 'Ensure the expected benefits of the solution actually happen over time', explain: 'Realisation can continue beyond the project.' },
  { id: 'z-pr-12', topic: 'PR', q: 'When deployment is ongoing in line with Delivery, what should also be ongoing?', options: ['Realisation', 'Feasibility', 'Pre-Project', 'Foundations'], correct: 'Realisation', explain: 'Continuous deployment implies continuous realisation.' },
  { id: 'z-pr-13', topic: 'PR', q: 'What is a Product Increment?', options: ['A stepwise refinement of a Product that meets the agreed Definition of Done', 'The whole solution including training and business change', 'A signed contract', 'The Sprint plan'], correct: 'A stepwise refinement of a Product that meets the agreed Definition of Done', explain: 'Each increment is additive and improves the previous.' },
  { id: 'z-pr-14', topic: 'PR', q: 'What is a Solution Increment?', options: ['A refinement of the overall Solution (may combine products + training, comms, business change)', 'A single line of code', 'The Product Backlog', 'A risk log'], correct: 'A refinement of the overall Solution (may combine products + training, comms, business change)', explain: 'The Solution meets the overarching project outcome.' },
  { id: 'z-pr-15', topic: 'PR', q: 'What are the three types of timebox AgilePM considers?', options: ['Project Timebox, Project Increment Timebox, Delivery Timeboxes (Sprints)', 'Daily, Weekly, Monthly', 'Short, Medium, Long', 'Planning, Build, Review'], correct: 'Project Timebox, Project Increment Timebox, Delivery Timeboxes (Sprints)', explain: 'The three nested timeboxes.' },
  { id: 'z-pr-16', topic: 'PR', q: 'What is a Timebox?', options: ['A fixed time period within which a team organises itself to deliver value', 'A budget line', 'A risk category', 'A backlog item'], correct: 'A fixed time period within which a team organises itself to deliver value', explain: 'Fixed time; scope flexes to fit.' },
  { id: 'z-pr-17', topic: 'PR', q: 'What is each Project Increment concluded with?', options: ['An Increment Review reflecting on the increments delivered', 'A contract signing', 'A new Business Case', 'A budget reset'], correct: 'An Increment Review reflecting on the increments delivered', explain: 'It reflects on Product and Solution Increments.' },
  { id: 'z-pr-18', topic: 'PR', q: 'In a "continuous delivery lifecycle", what happens regarding the Foundations Phase?', options: ['There is no return to Foundations; planning is ongoing via Cross-Team Refinement and Project Sprint Reviews', 'Foundations is revisited every Sprint', 'Foundations is skipped entirely', 'Foundations replaces Delivery'], correct: 'There is no return to Foundations; planning is ongoing via Cross-Team Refinement and Project Sprint Reviews', explain: 'Continuous delivery plans ahead without a Foundations return.' },
  { id: 'z-pr-19', topic: 'PR', q: 'Should every project go through the same lifecycle phases?', options: ['Yes, but the level of effort and formality in each phase varies', 'No, phases are optional and random', 'Only large projects use phases', 'Phases are chosen by the auditor'], correct: 'Yes, but the level of effort and formality in each phase varies', explain: 'Same phases, tailored effort/formality.' },
  { id: 'z-pr-20', topic: 'PR', q: 'What principle governs whether Project Artifacts are created?', options: ['They should only be created if they add real value', 'Every artifact must always be created', 'Artifacts are created only at project end', 'Only the auditor decides'], correct: 'They should only be created if they add real value', explain: 'Value-driven artifact creation.' },
  { id: 'z-pr-21', topic: 'PR', q: 'Why does AgilePM distinguish a Product from a Solution?', options: ['A Product is built by Delivery Teams; a Solution meets the overall outcome (may include more than products)', 'They are exactly the same', 'A Solution is smaller than a Product', 'A Product includes training and comms'], correct: 'A Product is built by Delivery Teams; a Solution meets the overall outcome (may include more than products)', explain: 'The Solution can combine products plus other items.' },
  { id: 'z-pr-22', topic: 'PR', q: 'What is the "Deployed Solution"?', options: ['Solution Increments combined and put into operational use', 'The Product Backlog', 'A test environment', 'A draft design'], correct: 'Solution Increments combined and put into operational use', explain: 'When deployed it becomes/adds to the Deployed Solution.' },
  { id: 'z-pr-23', topic: 'PR', q: 'A basic Delivery Timebox (Sprint) consists of which four timeboxed events?', options: ['Sprint Planning, Daily Scrum, Sprint Review, Sprint Retrospective', 'Kick-off, Build, Test, Sign-off', 'Vision, Backlog, Review, Release', 'Plan, Do, Check, Act'], correct: 'Sprint Planning, Daily Scrum, Sprint Review, Sprint Retrospective', explain: 'The four Sprint events.' },
  { id: 'z-pr-24', topic: 'PR', q: 'What two Project Roles are involved in the Pre-Project Phase?', options: ['Business Visionary and Business Sponsor', 'Project Manager and Scrum Master', 'Solution Architect and Developers', 'Product Owner and Business Advisor'], correct: 'Business Visionary and Business Sponsor', explain: 'Visionary defines vision; Sponsor provides funding/support.' },
  { id: 'z-pr-25', topic: 'PR', q: 'During Feasibility, which tool gives an early view of approach-based risk?', options: ['The Project Approach Questionnaire (PAQ)', 'The burn-down chart', 'The RACI matrix', 'The velocity chart'], correct: 'The Project Approach Questionnaire (PAQ)', explain: 'The PAQ is first used during Feasibility.' },
  { id: 'z-pr-26', topic: 'PR', q: 'What does "just enough detail, just in time" mean?', options: ['Defer detailed decisions to the last responsible moment', 'Document everything immediately', 'Skip all detail', 'Only the Sponsor adds detail'], correct: 'Defer detailed decisions to the last responsible moment', explain: 'AgilePM follows this principle for requirements/estimates.' },
  { id: 'z-pr-27', topic: 'PR', q: 'In which phase is the Product Backlog (Required) first created from the Solution Backlog?', options: ['By the end of the Foundations Phase', 'During Pre-Project', 'During Realisation', 'During Deployment only'], correct: 'By the end of the Foundations Phase', explain: 'Solution Backlog is split into Product Backlogs in Foundations.' },
  { id: 'z-pr-28', topic: 'PR', q: 'What is the main goal of the Pre-Project Phase?', options: ['Get approval for a small initial investment to explore whether the project is worth pursuing', 'Build a prototype', 'Complete the Business Case in full', 'Deploy a first release'], correct: 'Get approval for a small initial investment to explore whether the project is worth pursuing', explain: 'It is not about full feasibility yet.' },
  { id: 'z-pr-29', topic: 'PR', q: 'Which Project Artifacts are typically considered during the Feasibility Phase?', options: ['Business Case, Solution Backlog, SAD, DAD, MAD', 'Only the Delivery Plan', 'Only the Benefits Assessment', 'Only the Sprint Backlog'], correct: 'Business Case, Solution Backlog, SAD, DAD, MAD', explain: 'These evolutionary artifacts are outlined in Feasibility.' },
  { id: 'z-pr-30', topic: 'PR', q: 'What does the Feasibility Assessment (optional milestone) do?', options: ['Brings together the key findings of the Feasibility Phase for governance', 'Builds the solution', 'Measures benefits after go-live', 'Runs the Daily Scrum'], correct: 'Brings together the key findings of the Feasibility Phase for governance', explain: 'A management summary or replacement for the artifacts.' },
  { id: 'z-pr-31', topic: 'PR', q: 'What is the Foundations Summary?', options: ['A snapshot of key Project Artifacts at the end of Foundations for governance', 'The Pre-Project artifact', 'A risk register', 'The Sprint plan'], correct: 'A snapshot of key Project Artifacts at the end of Foundations for governance', explain: 'It helps assess viability/RoI before Delivery.' },
  { id: 'z-pr-32', topic: 'PR', q: 'What is an ideal "vertical slice" Product Increment?', options: ['One that contains all required elements (UI, logic, data) so it can be used', 'A single horizontal technology layer', 'A document only', 'A test plan'], correct: 'One that contains all required elements (UI, logic, data) so it can be used', explain: 'Horizontal-only layers delay value and risk integration issues.' },
  { id: 'z-pr-33', topic: 'PR', q: 'When is the Deployment Phase considered complete?', options: ['When the Solution Increment is in operational use and has reached a steady state', 'When the contract is signed', 'When the Business Case is approved', 'When the first Sprint ends'], correct: 'When the Solution Increment is in operational use and has reached a steady state', explain: 'Steady state = consistently providing business value.' },
  { id: 'z-pr-34', topic: 'PR', q: 'After the project, how might the Deployed Solution continue to evolve?', options: ['Continuous improvement, a future project, or a future client project', 'It must never change again', 'Only by re-running Feasibility', 'Only via a new contract'], correct: 'Continuous improvement, a future project, or a future client project', explain: 'Three ways the solution can keep evolving.' },

  // ===================================================================
  // ES — Requirements, Estimating & Prioritisation
  // ===================================================================
  { id: 'z-es-1', topic: 'ES', q: 'How does AgilePM define a Requirement?', options: ['A business or user need that must be met by the Solution', 'A signed contract clause', 'A line of code', 'A test case'], correct: 'A business or user need that must be met by the Solution', explain: 'Often written as User Stories.' },
  { id: 'z-es-2', topic: 'ES', q: 'What are the three types of backlog used in AgilePM?', options: ['Solution Backlog, Product Backlog, Sprint Backlog', 'Epic, Story, Task', 'Vision, Goal, Plan', 'Must, Should, Could'], correct: 'Solution Backlog, Product Backlog, Sprint Backlog', explain: 'The three backlog types.' },
  { id: 'z-es-3', topic: 'ES', q: 'What is the Solution Backlog?', options: ['An emergent ordered list of everything needed to make the solution viable', 'The Sprint plan', 'A list of completed tasks', 'A risk register'], correct: 'An emergent ordered list of everything needed to make the solution viable', explain: 'It serves the Solution Goal and Solution Vision.' },
  { id: 'z-es-4', topic: 'ES', q: 'What is the common User Story format (invented by Rachel Davies)?', options: ['As a <role>, I want <feature>, so that <benefit>', 'Given <x>, When <y>, Then <z>', 'Must / Should / Could / Won\'t', 'Who / What / When / Where'], correct: 'As a <role>, I want <feature>, so that <benefit>', explain: 'It captures who, what and why.' },
  { id: 'z-es-5', topic: 'ES', q: 'What format is commonly used for Acceptance Criteria (by Dan North)?', options: ['BDD: Given / When / Then', 'As a / I want / So that', 'Must / Should / Could', 'INVEST'], correct: 'BDD: Given / When / Then', explain: 'Behaviour-Driven Development scenarios.' },
  { id: 'z-es-6', topic: 'ES', q: 'What are the three levels of User Story detail?', options: ['Epic, User Story, Fine-grained User Story', 'Small, Medium, Large', 'Must, Should, Could', 'Vision, Goal, Task'], correct: 'Epic, User Story, Fine-grained User Story', explain: 'Detail increases as delivery approaches.' },
  { id: 'z-es-7', topic: 'ES', q: 'What level of User Story is typically used during the Feasibility Phase?', options: ['Epic User Stories', 'Fine-grained User Stories', 'Tasks', 'Acceptance tests'], correct: 'Epic User Stories', explain: 'Epics are broad and high-level.' },
  { id: 'z-es-8', topic: 'ES', q: 'What are the "Three Cs" of a User Story?', options: ['Card, Conversation, Confirmation', 'Clear, Concise, Complete', 'Cost, Customer, Contract', 'Create, Check, Commit'], correct: 'Card, Conversation, Confirmation', explain: 'Some add a fourth C: Context.' },
  { id: 'z-es-9', topic: 'ES', q: 'In the Three Cs, what does "Confirmation" provide?', options: ['A set of Acceptance Criteria for the story', 'The physical card', 'The team discussion', 'The Sprint Goal'], correct: 'A set of Acceptance Criteria for the story', explain: 'Confirmation = Acceptance Criteria.' },
  { id: 'z-es-10', topic: 'ES', q: 'What does the INVEST acronym stand for?', options: ['Independent, Negotiable, Valuable, Estimable, Small, Testable', 'Important, New, Valid, Easy, Simple, Tested', 'Iterative, Negotiated, Verified, Estimated, Scoped, Tracked', 'Independent, Necessary, Visible, Exact, Stable, Timed'], correct: 'Independent, Negotiable, Valuable, Estimable, Small, Testable', explain: 'Bill Wake\'s INVEST model.' },
  { id: 'z-es-11', topic: 'ES', q: 'In INVEST, "Independent" means...', options: ['Not dependent on other stories, to enable replanning', 'Cannot be changed', 'Has no business value', 'Is always large'], correct: 'Not dependent on other stories, to enable replanning', explain: 'Independence eases reprioritisation.' },
  { id: 'z-es-12', topic: 'ES', q: 'What is the Definition of Ready (DoR)?', options: ['Criteria a Product Backlog item must meet to be considered ready for a Sprint', 'The quality state of a completed increment', 'The list of all requirements', 'The Sprint Goal'], correct: 'Criteria a Product Backlog item must meet to be considered ready for a Sprint', explain: 'INVEST is a useful basis for the DoR.' },
  { id: 'z-es-13', topic: 'ES', q: 'What is the Definition of Done (DoD)?', options: ['A shared agreement of the minimum activities/quality each increment must satisfy to be complete', 'The criteria to start a story', 'The Sprint plan', 'The Product Vision'], correct: 'A shared agreement of the minimum activities/quality each increment must satisfy to be complete', explain: 'DoD makes "complete, usable, shippable" explicit.' },
  { id: 'z-es-14', topic: 'ES', q: 'How do Acceptance Criteria relate to the Definition of Done?', options: ['Meeting Acceptance Criteria is usually one part of meeting the DoD', 'They are identical', 'The DoD replaces Acceptance Criteria', 'Acceptance Criteria replace the DoD'], correct: 'Meeting Acceptance Criteria is usually one part of meeting the DoD', explain: 'AC are a minimum; the DoD is broader.' },
  { id: 'z-es-15', topic: 'ES', q: 'What distinguishes a Functional Requirement from a Non-Functional Requirement?', options: ['Functional = what the solution must do; NFR = how well it must perform', 'Functional = how well; NFR = what it does', 'They are the same thing', 'NFRs only apply to software'], correct: 'Functional = what the solution must do; NFR = how well it must perform', explain: 'NFRs cover quality attributes like performance.' },
  { id: 'z-es-16', topic: 'ES', q: 'Where might Non-Functional Requirements be captured?', options: ['In the Solution Architecture Definition (SAD)', 'In the Sprint Backlog only', 'In the Terms of Reference', 'In the Daily Scrum'], correct: 'In the Solution Architecture Definition (SAD)', explain: 'NFRs should be captured early in the SAD.' },
  { id: 'z-es-17', topic: 'ES', q: 'What forms the Minimum Usable Subset (MUST)?', options: ['The Must Have requirements', 'The Should Have requirements', 'The Could Have requirements', 'The Won\'t Have requirements'], correct: 'The Must Have requirements', explain: 'Only Must Haves are guaranteed.' },
  { id: 'z-es-18', topic: 'ES', q: 'A Must Have requirement cannot depend on...', options: ['Anything other than another Must Have', 'Another Must Have', 'The Business Case', 'The Definition of Done'], correct: 'Anything other than another Must Have', explain: 'Shoulds/Coulds might not be delivered.' },
  { id: 'z-es-19', topic: 'ES', q: 'What recommended share of total effort should Must Haves occupy?', options: ['No more than about 60%', 'About 80%', 'About 40%', '100%'], correct: 'No more than about 60%', explain: 'Leaving ~40% as contingency (Should/Could).' },
  { id: 'z-es-20', topic: 'ES', q: 'About what share of effort does AgilePM suggest for Could Haves?', options: ['Around 20%', 'Around 60%', 'Around 5%', 'Around 50%'], correct: 'Around 20%', explain: 'Could Haves are the main contingency buffer.' },
  { id: 'z-es-21', topic: 'ES', q: 'What are Won\'t Have (this time) requirements?', options: ['Those agreed not to be delivered in this timeframe (excluded from effort)', 'The highest priority items', 'Items delivered first', 'Items with no acceptance criteria'], correct: 'Those agreed not to be delivered in this timeframe (excluded from effort)', explain: 'Documented for transparency and expectation-setting.' },
  { id: 'z-es-22', topic: 'ES', q: 'When is MoSCoW effective?', options: ['Only when used together with a specified timeframe', 'At any time, without a timeframe', 'Only during Pre-Project', 'Only for non-functional requirements'], correct: 'Only when used together with a specified timeframe', explain: 'MoSCoW prioritises within a fixed timebox.' },
  { id: 'z-es-23', topic: 'ES', q: 'At which three levels can MoSCoW prioritisation be applied?', options: ['Project, Project Increment, and Delivery Timebox (Sprint)', 'Daily, Weekly, Monthly', 'Epic, Story, Task', 'Vision, Goal, Plan'], correct: 'Project, Project Increment, and Delivery Timebox (Sprint)', explain: 'Priority can differ at each level.' },
  { id: 'z-es-24', topic: 'ES', q: 'Does MoSCoW dictate the order of delivery?', options: ['No — it describes importance, not order of delivery', 'Yes — Musts are always built first', 'Yes — Coulds are built first', 'Only in regulated projects'], correct: 'No — it describes importance, not order of delivery', explain: 'Order also depends on dependencies and efficiency.' },
  { id: 'z-es-25', topic: 'ES', q: 'A useful MoSCoW technique is to start with all requirements as...', options: ['Won\'t Haves, promoting them only with strong justification', 'Must Haves, demoting them if needed', 'Could Haves, then sorting alphabetically', 'Should Haves, by default'], correct: 'Won\'t Haves, promoting them only with strong justification', explain: 'This prevents everything becoming a Must Have.' },
  { id: 'z-es-26', topic: 'ES', q: 'On what should benefit estimates be based?', options: ['Delivering Must Have and Should Have requirements', 'Delivering only Must Haves', 'Delivering everything including Coulds', 'Delivering Won\'t Haves'], correct: 'Delivering Must Have and Should Have requirements', explain: 'Cost covers full scope; benefits on Musts + Shoulds.' },
  { id: 'z-es-27', topic: 'ES', q: 'What should cost estimates cover?', options: ['The full scope of requirements', 'Only the Must Haves', 'Only the first Sprint', 'Only the Could Haves'], correct: 'The full scope of requirements', explain: 'Cost covers the whole scope.' },
  { id: 'z-es-28', topic: 'ES', q: 'What is "scope creep"?', options: ['A change in the breadth of requirements that must be managed', 'A change in the depth of a requirement', 'A reduction in quality', 'A change to the team'], correct: 'A change in the breadth of requirements that must be managed', explain: 'Breadth change = scope creep; depth change uses contingency.' },
  { id: 'z-es-29', topic: 'ES', q: 'A change in the DEPTH of a requirement should be handled using...', options: ['The contingency planned via MoSCoW', 'A new contract', 'A change to time and cost', 'A reduction in quality'], correct: 'The contingency planned via MoSCoW', explain: 'Depth changes are absorbed by MoSCoW contingency.' },
  { id: 'z-es-30', topic: 'ES', q: 'What are the two common styles of estimating in AgilePM/Scrum?', options: ['Estimating by analogy and estimating by decomposition', 'Top-down and contractual', 'Fixed-price and time-and-materials', 'Guessing and averaging'], correct: 'Estimating by analogy and estimating by decomposition', explain: 'Analogy (comparison) and decomposition (break down).' },
  { id: 'z-es-31', topic: 'ES', q: 'Who is responsible for estimating the work?', options: ['The people doing the work (the Developers)', 'The Project Manager', 'The Business Sponsor', 'The auditor'], correct: 'The people doing the work (the Developers)', explain: 'Those who deliver it estimate it.' },
  { id: 'z-es-32', topic: 'ES', q: 'What is T-Shirt sizing best for?', options: ['Fast, simple early-stage estimation when details are limited', 'Precise final costing', 'Tracking velocity', 'Auditing compliance'], correct: 'Fast, simple early-stage estimation when details are limited', explain: 'S/M/L/XL categories for early phases.' },
  { id: 'z-es-33', topic: 'ES', q: 'What scale do Story Points typically use?', options: ['A non-linear Fibonacci-like sequence (1, 2, 3, 5, 8, 13, 20...)', 'A strict linear hours scale', 'Percentages of the project', 'Letters A-F'], correct: 'A non-linear Fibonacci-like sequence (1, 2, 3, 5, 8, 13, 20...)', explain: 'Larger numbers reflect greater uncertainty.' },
  { id: 'z-es-34', topic: 'ES', q: 'What is Velocity?', options: ['The average story points a team completes per Sprint, used to forecast', 'The speed of typing code', 'The number of Sprints in a project', 'The pass mark of the exam'], correct: 'The average story points a team completes per Sprint, used to forecast', explain: 'Velocity is unique to each team and measures output.' },
  { id: 'z-es-35', topic: 'ES', q: 'Velocity is a measure of...', options: ['Output, not outcomes', 'Outcomes, not output', 'Quality', 'Risk'], correct: 'Output, not outcomes', explain: 'Don\'t use velocity as the sole measure of progress.' },
  { id: 'z-es-36', topic: 'ES', q: 'What is Planning Poker?', options: ['A card-based comparative estimating technique using a Fibonacci-like scale', 'A gambling game', 'A risk workshop', 'A deployment method'], correct: 'A card-based comparative estimating technique using a Fibonacci-like scale', explain: 'It uses the Wideband Delphi technique.' },
  { id: 'z-es-37', topic: 'ES', q: 'In Planning Poker, if estimates are close (e.g. 3s and 5s), which value is chosen?', options: ['The higher value', 'The lower value', 'The average', 'Re-vote until identical'], correct: 'The higher value', explain: 'You must pick an available card value; choose the higher.' },
  { id: 'z-es-38', topic: 'ES', q: 'Why use cards (face down) in Planning Poker?', options: ['To stop estimators influencing each other before revealing', 'To make it competitive', 'To speed up typing', 'To satisfy an auditor'], correct: 'To stop estimators influencing each other before revealing', explain: 'It produces more honest, independent estimates.' },
  { id: 'z-es-39', topic: 'ES', q: 'What is Commitment-based planning used for?', options: ['Estimating a team\'s velocity by selecting items until they can no longer commit', 'Signing a fixed-price contract', 'Auditing compliance', 'Deploying increments'], correct: 'Estimating a team\'s velocity by selecting items until they can no longer commit', explain: 'Used when velocity is unknown (Foundations / new team).' },
  { id: 'z-es-40', topic: 'ES', q: 'Estimating by Decomposition is also known as...', options: ['Bottom-Up Estimating', 'Top-Down Estimating', 'Comparative Estimating', 'Wideband Delphi'], correct: 'Bottom-Up Estimating', explain: 'Break work into tasks and sum the estimates.' },

  // ===================================================================
  // PC — Planning & Control
  // ===================================================================
  { id: 'z-pc-1', topic: 'PC', q: 'What are AgilePM\'s three key planning concepts?', options: ['Outcome-based planning, planning to sensible horizons, plan & re-plan on best estimates', 'Fixed planning, detailed planning, signed planning', 'Vision, backlog, sprint', 'Plan, do, check'], correct: 'Outcome-based planning, planning to sensible horizons, plan & re-plan on best estimates', explain: 'The three planning concepts.' },
  { id: 'z-pc-2', topic: 'PC', q: 'What are AgilePM\'s four control concepts?', options: ['Outcome-based measurement, transparency, responding to change, management by exception', 'Reporting, auditing, signing, escalating', 'Scope, time, cost, quality', 'Plan, build, test, deploy'], correct: 'Outcome-based measurement, transparency, responding to change, management by exception', explain: 'The four control concepts.' },
  { id: 'z-pc-3', topic: 'PC', q: 'What is Management by Exception?', options: ['Only major deviations from the plan are escalated; minor ones handled by the team', 'All deviations are escalated immediately', 'No deviations are ever escalated', 'Only the Sponsor manages deviations'], correct: 'Only major deviations from the plan are escalated; minor ones handled by the team', explain: 'It reduces oversight and empowers teams.' },
  { id: 'z-pc-4', topic: 'PC', q: 'When does an "exception" arise for a Delivery Team?', options: ['When the Sprint Goal is at risk (e.g. Must Haves won\'t be delivered)', 'When a Could Have is dropped', 'At the start of every Sprint', 'When documentation is late'], correct: 'When the Sprint Goal is at risk (e.g. Must Haves won\'t be delivered)', explain: 'Not achieving the Sprint Goal is a major deviation.' },
  { id: 'z-pc-5', topic: 'PC', q: 'What are AgilePM\'s three planning horizons?', options: ['Long-term, Medium-term, Short-term', 'Daily, Weekly, Monthly', 'Vision, Goal, Task', 'Pre-project, Feasibility, Foundations'], correct: 'Long-term, Medium-term, Short-term', explain: 'Long (whole project), medium (increment), short (Sprint).' },
  { id: 'z-pc-6', topic: 'PC', q: 'Short-term planning in AgilePM is managed by...', options: ['Sprint Planning', 'The Business Case', 'The Terms of Reference', 'The Benefits Assessment'], correct: 'Sprint Planning', explain: 'Short-term = Sprint Planning (how to achieve the Sprint Goal).' },
  { id: 'z-pc-7', topic: 'PC', q: 'What is the most common Sprint length?', options: ['Two weeks', 'One day', 'Six weeks', 'Three months'], correct: 'Two weeks', explain: 'Two weeks is the most common cadence.' },
  { id: 'z-pc-8', topic: 'PC', q: 'What is the maximum recommended Sprint length in AgilePM?', options: ['Six weeks', 'Two weeks', 'Three months', 'One week'], correct: 'Six weeks', explain: 'One to four weeks is normal; six is the maximum.' },
  { id: 'z-pc-9', topic: 'PC', q: 'What does a burn-down chart show?', options: ['Remaining work compared to the time left', 'Work completed over time', 'Item status across columns', 'Team velocity history'], correct: 'Remaining work compared to the time left', explain: 'Burn-down tracks remaining work.' },
  { id: 'z-pc-10', topic: 'PC', q: 'What does a burn-up chart show?', options: ['Work completed over time', 'Remaining work vs time', 'Bottlenecks in workflow', 'Risk exposure'], correct: 'Work completed over time', explain: 'Burn-up shows steady progress completed.' },
  { id: 'z-pc-11', topic: 'PC', q: 'What does a cumulative flow chart track?', options: ['The status of work items over time (e.g. not started, in progress, done)', 'Only remaining work', 'Only completed work', 'Only the budget'], correct: 'The status of work items over time (e.g. not started, in progress, done)', explain: 'It reveals workflow and bottlenecks.' },
  { id: 'z-pc-12', topic: 'PC', q: 'What should tracking charts NOT be used for?', options: ['Judging or comparing team performance', 'Supporting inspection and adaptation', 'Maintaining transparency', 'Helping a team manage its work'], correct: 'Judging or comparing team performance', explain: 'They are working tools, not performance scores.' },
  { id: 'z-pc-13', topic: 'PC', q: 'Where is the Sprint Backlog usually visualised?', options: ['On a Team Board (physical or digital)', 'In the Business Case', 'In the Terms of Reference', 'In the contract'], correct: 'On a Team Board (physical or digital)', explain: 'A visible board shows who does what toward the Sprint Goal.' },
  { id: 'z-pc-14', topic: 'PC', q: 'What is Cross-Team Refinement (CTR) used for?', options: ['Keeping multiple Delivery Teams aligned by inspecting/adapting artifacts', 'Running the Daily Scrum', 'Signing the contract', 'Approving the budget'], correct: 'Keeping multiple Delivery Teams aligned by inspecting/adapting artifacts', explain: 'CTR also inspects Project Artifacts, not just the backlog.' },
  { id: 'z-pc-15', topic: 'PC', q: 'What is the suggested duration and frequency of Cross-Team Refinement?', options: ['1–3 hours, at least once every Sprint', '8 hours, once per project', '15 minutes, daily', 'Half a day, monthly'], correct: '1–3 hours, at least once every Sprint', explain: 'Teams experiment with what is effective.' },
  { id: 'z-pc-16', topic: 'PC', q: 'What is a Scrum of Scrums (SoS)?', options: ['Representatives from each team meeting to share updates and manage dependencies', 'A single team\'s Daily Scrum', 'A Sprint Review', 'A retrospective'], correct: 'Representatives from each team meeting to share updates and manage dependencies', explain: 'Common across Scrum-based scaling.' },
  { id: 'z-pc-17', topic: 'PC', q: 'What is the timebox for a Project Sprint Review (one-month Sprint)?', options: ['Maximum 4 hours', 'Maximum 8 hours', 'Maximum 3 hours', '15 minutes'], correct: 'Maximum 4 hours', explain: 'Like a normal Sprint Review, reduced for shorter Sprints.' },
  { id: 'z-pc-18', topic: 'PC', q: 'What is outcome-based measurement?', options: ['Tracking progress by delivered value, not just tasks completed', 'Counting hours logged', 'Counting documents produced', 'Counting meetings held'], correct: 'Tracking progress by delivered value, not just tasks completed', explain: 'Outcome = value realised; output = the deliverable.' },
  { id: 'z-pc-19', topic: 'PC', q: 'When should the Delivery Plan typically be baselined during the Delivery Phase?', options: ['Usually at the end of each Sprint', 'Only at project start', 'Never', 'Only at Deployment'], correct: 'Usually at the end of each Sprint', explain: 'Baselining tracks progress and demonstrates control.' },
  { id: 'z-pc-20', topic: 'PC', q: 'Who is responsible for high-level planning, while teams self-manage detail?', options: ['The Project Manager', 'The Scrum Master', 'The Business Sponsor', 'The auditor'], correct: 'The Project Manager', explain: 'PM oversees high-level planning; teams plan their own work.' },
  { id: 'z-pc-21', topic: 'PC', q: 'What is the difference between an output and an outcome?', options: ['Output is the deliverable; outcome is the value realised when used', 'They are identical', 'Output is value; outcome is the deliverable', 'Outcome is the budget'], correct: 'Output is the deliverable; outcome is the value realised when used', explain: 'AgilePM measures outcomes, not just outputs.' },
  { id: 'z-pc-22', topic: 'PC', q: 'When should outstanding backlog items have their priorities reviewed, as a minimum?', options: ['At the end of each Sprint and each Project Increment', 'Only at project end', 'Only during Pre-Project', 'Only if an audit occurs'], correct: 'At the end of each Sprint and each Project Increment', explain: 'Continuous re-prioritisation keeps alignment.' },
  { id: 'z-pc-23', topic: 'PC', q: 'When introducing new requirements between increments, what must NOT increase?', options: ['The percentage of Must Have effort', 'The number of Could Haves', 'The team size', 'The Sprint length'], correct: 'The percentage of Must Have effort', explain: 'Too many Musts threatens deadlines.' },
  { id: 'z-pc-24', topic: 'PC', q: 'Why revisit the Foundations Phase between Project Increments?', options: ['To confirm viability, refine requirements and update the Delivery Plan', 'To restart the project', 'To cancel the contract', 'To re-run Pre-Project'], correct: 'To confirm viability, refine requirements and update the Delivery Plan', explain: 'It keeps the project justified and aligned.' },
  { id: 'z-pc-25', topic: 'PC', q: 'During Project Sprint Planning, who facilitates with the Product Owner and team representatives?', options: ['The Agile Project Manager', 'The Business Sponsor', 'An external auditor', 'The Business Visionary alone'], correct: 'The Agile Project Manager', explain: 'PM facilitates project-level Sprint Planning.' },
  { id: 'z-pc-26', topic: 'PC', q: 'What is the output of Delivery Team Sprint Planning?', options: ['A Sprint Backlog for each Delivery Team', 'A signed contract', 'The Business Case', 'The Terms of Reference'], correct: 'A Sprint Backlog for each Delivery Team', explain: 'Team Sprint Planning is effectively Topic 3 (how).' },
  { id: 'z-pc-27', topic: 'PC', q: 'Who attends the joint Project Sprint Retrospective?', options: ['The whole Project Organisation except the Business Sponsor and Business Visionary', 'Only the Scrum Masters', 'Only the Developers', 'Only external stakeholders'], correct: 'The whole Project Organisation except the Business Sponsor and Business Visionary', explain: 'Held after team retrospectives.' },
  { id: 'z-pc-28', topic: 'PC', q: 'What is the primary purpose of tracking charts (burn-down/up, CFD)?', options: ['To support inspection and adaptation (empiricism)', 'To rank teams', 'To set salaries', 'To satisfy contracts'], correct: 'To support inspection and adaptation (empiricism)', explain: 'They aid transparency and timely adjustment.' },
  { id: 'z-pc-29', topic: 'PC', q: 'During the Delivery Phase, who works to coordinate work outside the Delivery Teams?', options: ['The Project Manager', 'The Developers', 'The auditor', 'The Business Sponsor'], correct: 'The Project Manager', explain: 'The PM coordinates cross-team alignment and dependencies.' },
  { id: 'z-pc-30', topic: 'PC', q: 'For coordination across teams, Sprints should have...', options: ['A standard length / cadence', 'Different lengths each time', 'No fixed length', 'A length set by the auditor'], correct: 'A standard length / cadence', explain: 'Consistent cadence eases coordination.' },

  // ===================================================================
  // RK — Risk Management & the Project Approach
  // ===================================================================
  { id: 'z-rk-1', topic: 'RK', q: 'How is risk generally defined in a project?', options: ['The possibility of something happening that could affect the project\'s goals', 'A guaranteed failure', 'A type of contract', 'A backlog item'], correct: 'The possibility of something happening that could affect the project\'s goals', explain: 'Risks often arise due to VUCA.' },
  { id: 'z-rk-2', topic: 'RK', q: 'Risks in a project often arise due to...', options: ['VUCA', 'Too much documentation', 'Having a Product Owner', 'Using Sprints'], correct: 'VUCA', explain: 'Volatility, Uncertainty, Complexity, Ambiguity drive risk.' },
  { id: 'z-rk-3', topic: 'RK', q: 'Who is responsible for identifying and owning Value Ownership-based risk?', options: ['The Business Visionary', 'The Solution Architect', 'The Project Manager', 'The Scrum Master'], correct: 'The Business Visionary', explain: 'Value Ownership risk = Business Visionary.' },
  { id: 'z-rk-4', topic: 'RK', q: 'Who is responsible for identifying and owning Solution Delivery-based risk?', options: ['The Solution Architect', 'The Business Visionary', 'The Project Manager', 'The Product Owner'], correct: 'The Solution Architect', explain: 'Solution Delivery risk = Solution Architect.' },
  { id: 'z-rk-5', topic: 'RK', q: 'Who is responsible for risk associated with Delivery Enablement (organisation, schedule, dependencies)?', options: ['The Project Manager', 'The Business Sponsor', 'The Developers', 'The Business Visionary'], correct: 'The Project Manager', explain: 'Delivery Enablement risk = Project Manager.' },
  { id: 'z-rk-6', topic: 'RK', q: 'What is the Project Approach Questionnaire (PAQ)?', options: ['A tool to identify risks when using AgilePM and guide tailoring', 'A contract template', 'A budget spreadsheet', 'A test plan'], correct: 'A tool to identify risks when using AgilePM and guide tailoring', explain: 'The PAQ helps adapt the approach to reduce risk.' },
  { id: 'z-rk-7', topic: 'RK', q: 'How many statements are in the PAQ?', options: ['17', '12', '8', '25'], correct: '17', explain: 'The PAQ has 17 statements.' },
  { id: 'z-rk-8', topic: 'RK', q: 'On what scale are PAQ statements rated?', options: ['Strongly Agree to Strongly Disagree (consensus opinion)', 'Pass/Fail', '1 to 100', 'Red/Amber/Green'], correct: 'Strongly Agree to Strongly Disagree (consensus opinion)', explain: 'A consensus opinion scale.' },
  { id: 'z-rk-9', topic: 'RK', q: 'If a PAQ statement is considered NOT true, what does it indicate?', options: ['A risk to using AgilePM successfully that must be resolved or tailored for', 'That the project is complete', 'That documentation is missing', 'That the budget is wrong'], correct: 'A risk to using AgilePM successfully that must be resolved or tailored for', explain: 'Disagreement signals a risk to address.' },
  { id: 'z-rk-10', topic: 'RK', q: 'When is the PAQ first completed?', options: ['During the Feasibility Phase (reviewed again at end of Foundations)', 'Only at project closure', 'During Deployment', 'Only if an audit requires it'], correct: 'During the Feasibility Phase (reviewed again at end of Foundations)', explain: 'Early use helps preventive action; tailoring happens in Foundations.' },
  { id: 'z-rk-11', topic: 'RK', q: 'When applied correctly, how does AgilePM treat risk management?', options: ['It manages risk through normal day-to-day agile activities (formal process only if regulated)', 'It always requires a separate heavyweight process', 'It ignores risk entirely', 'It delegates risk to an external auditor'], correct: 'It manages risk through normal day-to-day agile activities (formal process only if regulated)', explain: 'Separate formal risk management is mainly for regulated/safety contexts.' },
  { id: 'z-rk-12', topic: 'RK', q: 'PAQ Statement 1 concerns which of the following?', options: ['All members understand and accept the combined AgilePM and Scrum approaches', 'The budget is fully approved', 'The contract is signed', 'The solution is deployed'], correct: 'All members understand and accept the combined AgilePM and Scrum approaches', explain: 'Lack of understanding/training is a common risk.' },
  { id: 'z-rk-13', topic: 'RK', q: 'If the PAQ shows the team lacks understanding of AgilePM/Scrum, a typical action is...', options: ['Provide training and briefings (or use an Accredited Training Organisation)', 'Cancel the project immediately', 'Switch to fixed-price contracts', 'Remove the Product Owner'], correct: 'Provide training and briefings (or use an Accredited Training Organisation)', explain: 'Training resolves the common risk.' },
  { id: 'z-rk-14', topic: 'RK', q: 'If the Business Visionary cannot be engaged despite coaching, the best course of action may be to...', options: ['Refuse to continue the project until ownership is resolved', 'Proceed anyway with assumptions', 'Replace them with a Developer', 'Ignore the Business Case'], correct: 'Refuse to continue the project until ownership is resolved', explain: 'Strong Value Ownership is essential.' },
  { id: 'z-rk-15', topic: 'RK', q: 'If empowerment of the Delivery Team is not supported by the organisation, then...', options: ['AgilePM cannot be fully adopted (incompatible with strict top-down control)', 'AgilePM works perfectly anyway', 'Only the Scrum Master is affected', 'The budget must increase'], correct: 'AgilePM cannot be fully adopted (incompatible with strict top-down control)', explain: 'Empowerment underpins AgilePM and Scrum.' },
  { id: 'z-rk-16', topic: 'RK', q: 'What three types of constraints might affect applying AgilePM (PAQ Statement 17)?', options: ['Internal standards, external (regulatory) standards, commercial arrangements', 'Budget, schedule, scope', 'People, process, tools', 'Time, cost, quality'], correct: 'Internal standards, external (regulatory) standards, commercial arrangements', explain: 'These three may require additional consideration.' },
  { id: 'z-rk-17', topic: 'RK', q: 'Why are fixed-price, fixed-scope contracts problematic for AgilePM?', options: ['AgilePM works best in flexible environments; such contracts undermine its principles', 'They are too cheap', 'They deliver too quickly', 'They require too few people'], correct: 'AgilePM works best in flexible environments; such contracts undermine its principles', explain: 'Consider MoSCoW-aware contracts instead.' },
  { id: 'z-rk-18', topic: 'RK', q: 'How should regulatory compliance ideally be built into delivery?', options: ['Into the Definition of Done and Acceptance Criteria, supported by a Business Advisor', 'Only in a separate document at the end', 'By ignoring agile entirely', 'By the auditor writing the code'], correct: 'Into the Definition of Done and Acceptance Criteria, supported by a Business Advisor', explain: 'Build compliance into the work itself.' },
  { id: 'z-rk-19', topic: 'RK', q: 'In AgilePM/Scrum, Developers are generally expected to work...', options: ['Full-time on the project, at least for the duration of a Project Increment', 'Part-time only', 'Only during Foundations', 'Only on Fridays'], correct: 'Full-time on the project, at least for the duration of a Project Increment', explain: 'Part-time members make Sprint-based delivery difficult.' },
  { id: 'z-rk-20', topic: 'RK', q: 'How does an agile project compare to non-agile in coping with VUCA?', options: ['Agile projects are generally less affected by VUCA', 'Agile projects are more affected by VUCA', 'There is no difference', 'Agile removes all VUCA'], correct: 'Agile projects are generally less affected by VUCA', explain: 'Adaptability and collaboration reduce VUCA impact.' },
  { id: 'z-rk-21', topic: 'RK', q: 'If all PAQ statements are agreed/strongly agreed, what does it suggest?', options: ['AgilePM with Scrum should work effectively (though this is rare)', 'The project will definitely fail', 'No training is ever needed', 'The contract is invalid'], correct: 'AgilePM with Scrum should work effectively (though this is rare)', explain: 'Full agreement is rare, especially for organisations new to agility.' },
  { id: 'z-rk-22', topic: 'RK', q: 'During Feasibility, which assessment helps gauge complexity-related risk and team organisation?', options: ['The AgilePM Project Approach Questionnaire (PAQ)', 'The Benefits Assessment', 'The burn-down chart', 'The Sprint Review Record'], correct: 'The AgilePM Project Approach Questionnaire (PAQ)', explain: 'The PAQ informs how many teams and how to apply AgilePM.' },

  // ===================================================================
  // GV — Governance, Compliance & Products
  // ===================================================================
  { id: 'z-gv-1', topic: 'GV', q: 'What is Governance in the project context?', options: ['The processes, structures and controls ensuring a project is well managed and meeting its objectives', 'Strictly following every rule regardless of outcome', 'A type of contract', 'A backlog refinement technique'], correct: 'The processes, structures and controls ensuring a project is well managed and meeting its objectives', explain: 'Governance and empiricism need not conflict.' },
  { id: 'z-gv-2', topic: 'GV', q: 'What is Empiricism?', options: ['Learning through experience and deciding based on observed real-world results', 'Following the plan rigidly', 'Maximising documentation', 'Negotiating contracts'], correct: 'Learning through experience and deciding based on observed real-world results', explain: 'Empiricism complements good governance.' },
  { id: 'z-gv-3', topic: 'GV', q: 'What does the Cone (Core) of Uncertainty (Barry Boehm) describe?', options: ['Early estimates are vague and become more accurate as the project progresses', 'Estimates get worse over time', 'Estimates are always exact', 'Estimates are irrelevant'], correct: 'Early estimates are vague and become more accurate as the project progresses', explain: 'Accuracy narrows through the lifecycle.' },
  { id: 'z-gv-4', topic: 'GV', q: 'How does AgilePM recommend giving estimates?', options: ['As ranges, not single figures', 'As a single exact figure', 'As a percentage of profit', 'Never give estimates'], correct: 'As ranges, not single figures', explain: 'Ranges reflect uncertainty honestly.' },
  { id: 'z-gv-5', topic: 'GV', q: 'If a Business Sponsor insists on a single-figure estimate, who must choose it?', options: ['The Business Sponsor (from the range provided)', 'The Developers', 'The Scrum Master', 'The auditor'], correct: 'The Business Sponsor (from the range provided)', explain: 'The decision should not fall on the estimator.' },
  { id: 'z-gv-6', topic: 'GV', q: 'By default, AgilePM controls time and cost through which two practices?', options: ['MoSCoW prioritisation and timeboxing', 'Contracts and audits', 'Velocity and burn-down', 'Vision and roadmap'], correct: 'MoSCoW prioritisation and timeboxing', explain: 'Scope flexes; time and cost stay fixed.' },
  { id: 'z-gv-7', topic: 'GV', q: 'What are the two kinds of quality AgilePM considers?', options: ['Solution quality and Process quality', 'Internal and external quality', 'High and low quality', 'Functional and non-functional quality'], correct: 'Solution quality and Process quality', explain: 'Solution = meets need; Process = built correctly/lawfully.' },
  { id: 'z-gv-8', topic: 'GV', q: 'Who can usually achieve regulatory compliance by being actively involved in the project?', options: ['Someone qualified in regulatory matters acting as a Business Advisor', 'The Scrum Master alone', 'The Developers alone', 'An external auditor only'], correct: 'Someone qualified in regulatory matters acting as a Business Advisor', explain: 'The Business Advisor supports compliance throughout.' },
  { id: 'z-gv-9', topic: 'GV', q: 'Which AgilePM Project Artifacts can be customised to show compliance?', options: ['Solution Architecture Definition, Sprint Review Records, Project Review Reports', 'Only the contract', 'Only the budget', 'Only the Daily Scrum notes'], correct: 'Solution Architecture Definition, Sprint Review Records, Project Review Reports', explain: 'These can be adapted to demonstrate control.' },
  { id: 'z-gv-10', topic: 'GV', q: 'In the MoSCoW Business Case, the "Worst Case" benefit is based on...', options: ['Just the Must Haves', 'All Musts and Shoulds', 'All Musts, Shoulds and Coulds', 'The Won\'t Haves'], correct: 'Just the Must Haves', explain: 'Worst case = the guaranteed minimum.' },
  { id: 'z-gv-11', topic: 'GV', q: 'In the MoSCoW Business Case, the "Expected Case" benefit is based on...', options: ['All Musts and Shoulds', 'Just the Musts', 'All Musts, Shoulds and Coulds', 'Just the Coulds'], correct: 'All Musts and Shoulds', explain: 'Expected case = Musts + Shoulds.' },
  { id: 'z-gv-12', topic: 'GV', q: 'In the MoSCoW Business Case, the "Best Case" benefit is based on...', options: ['All Musts, Shoulds and Coulds', 'Just the Musts', 'All Musts and Shoulds', 'Just the Coulds'], correct: 'All Musts, Shoulds and Coulds', explain: 'Best case = everything delivered.' },
  { id: 'z-gv-13', topic: 'GV', q: 'What does a Benefits Assessment measure?', options: ['The real, observed benefits after the solution has been used in the real world', 'The estimated cost before starting', 'The Sprint velocity', 'The number of Must Haves'], correct: 'The real, observed benefits after the solution has been used in the real world', explain: 'Measured after live use.' },
  { id: 'z-gv-14', topic: 'GV', q: 'What does RACI stand for?', options: ['Responsible, Accountable, Consulted, Informed', 'Review, Approve, Control, Inspect', 'Risk, Assurance, Compliance, Integrity', 'Record, Audit, Certify, Issue'], correct: 'Responsible, Accountable, Consulted, Informed', explain: 'RACI maps roles to artifacts.' },
  { id: 'z-gv-15', topic: 'GV', q: 'What are the two types of Project Artifacts AgilePM defines?', options: ['Evolutionary and Milestone artifacts', 'Required and Optional artifacts', 'Internal and External artifacts', 'Draft and Final artifacts'], correct: 'Evolutionary and Milestone artifacts', explain: 'Evolutionary develop over time; milestone mark checkpoints.' },
  { id: 'z-gv-16', topic: 'GV', q: 'For the Business Case, who is Accountable (RACI)?', options: ['The Business Sponsor', 'The Project Manager', 'The Solution Architect', 'The Product Owner'], correct: 'The Business Sponsor', explain: 'Business Visionary Responsible; Business Sponsor Accountable.' },
  { id: 'z-gv-17', topic: 'GV', q: 'For the Delivery Plan, who is Responsible and Accountable (RACI)?', options: ['The Project Manager', 'The Business Sponsor', 'The Solution Architect', 'The Developers'], correct: 'The Project Manager', explain: 'The PM owns the Delivery Plan.' },
  { id: 'z-gv-18', topic: 'GV', q: 'For the Product Backlog, who is Responsible (RACI)?', options: ['The Product Owner', 'The Developers', 'The Project Manager', 'The Business Sponsor'], correct: 'The Product Owner', explain: 'PO Responsible; Business Visionary Accountable.' },
  { id: 'z-gv-19', topic: 'GV', q: 'For the Sprint Backlog, who is Responsible (RACI)?', options: ['The Developers', 'The Product Owner', 'The Scrum Master', 'The Project Manager'], correct: 'The Developers', explain: 'Developers Responsible; Product Owner Accountable.' },
  { id: 'z-gv-20', topic: 'GV', q: 'How can compliance-based governance conflict with agile values?', options: ['By emphasising processes/documents/contracts/plans over the agile Manifesto values', 'By delivering too much value', 'By empowering teams too much', 'By reducing documentation'], correct: 'By emphasising processes/documents/contracts/plans over the agile Manifesto values', explain: 'These are the Manifesto statements in reverse.' },
  { id: 'z-gv-21', topic: 'GV', q: 'What is the recommended approach to meeting a regulation in an agile way?', options: ['Understand what the regulation is trying to achieve, then meet that goal in an agile way', 'Always abandon agile for regulated work', 'Ignore the regulation', 'Let the auditor write the solution'], correct: 'Understand what the regulation is trying to achieve, then meet that goal in an agile way', explain: 'Regulations often allow agile if the intent is met.' },
  { id: 'z-gv-22', topic: 'GV', q: 'Why might an auditor not recognise a User Story or Sprint Backlog as valid evidence?', options: ['They may not understand agile planning unless it is explained clearly', 'Because they are always invalid', 'Because they are confidential', 'Because they are too long'], correct: 'They may not understand agile planning unless it is explained clearly', explain: 'Help auditors understand what valid agile evidence looks like.' },
  { id: 'z-gv-23', topic: 'GV', q: 'What must the Business Sponsor do throughout the project (financial governance)?', options: ['Make the initial business case, keep reviewing it, and stop the project if it no longer makes sense', 'Write all the code', 'Run the Daily Scrum', 'Set the Definition of Done'], correct: 'Make the initial business case, keep reviewing it, and stop the project if it no longer makes sense', explain: 'The Sponsor owns ongoing financial viability.' },
  { id: 'z-gv-24', topic: 'GV', q: 'When can Delivery Teams give more solid estimates?', options: ['Only after the Foundations Phase', 'Before Pre-Project', 'Never', 'Only after Deployment'], correct: 'Only after the Foundations Phase', explain: 'Before that, all estimates are rough indicators.' },
  { id: 'z-gv-25', topic: 'GV', q: 'In Figure A.1, what do "orange" Project Artifacts focus on?', options: ['Value Ownership needs', 'Building the solution', 'Managing/controlling the project', 'Regulatory audit only'], correct: 'Value Ownership needs', explain: 'Orange = value ownership; green = solution; purple = project management.' },
  { id: 'z-gv-26', topic: 'GV', q: 'What does a "(G)" marker on an artifact indicate?', options: ['It may also be used in governance activities (gateways/compliance)', 'It is a green artifact', 'It is the Sponsor\'s artifact', 'It is optional'], correct: 'It may also be used in governance activities (gateways/compliance)', explain: 'G-marked artifacts support governance.' },
]
